// Type for ChatDatabase instance to avoid circular import
// Only includes properties/methods needed by this module.
// NOTE: getChatKey/setChatKey/clearChatKey have been removed — use chatKeyManager directly.
interface ChatDatabaseInstance {
  db: IDBDatabase | null;
  CHATS_STORE_NAME: string;
  init(): Promise<void>;
  getTransaction(
    storeNames: string | string[],
    mode: IDBTransactionMode,
  ): Promise<IDBTransaction>;

  // Chat retrieval (for IDB integrity checks)
  getChat(chatId: string, transaction?: IDBTransaction): Promise<Chat | null>;
}

// Store name constant for messages (needed for deleteChat)
const MESSAGES_STORE_NAME = "messages";
const EMBEDS_STORE_NAME = "embeds";
const EMBED_KEYS_STORE_NAME = "embed_keys";
const MAX_INFERRED_DELETE_EMBEDS = 100;
const MAX_INFERRED_DELETE_PENDING_PROBE = 256;
const MAX_INFERRED_DELETE_KEYS_PER_EMBED = 100;

/**
 * Apply Phase 2's inferred absence only when the same IndexedDB transaction
 * proves there is no sealed turn awaiting a canonical acknowledgement.
 * Explicit server tombstones use deleteChat instead. The four stores share one
 * transaction, so a new journal/head cannot arrive between the guard and
 * cleanup. Admission limits retain the local chat when absence is uncertain.
 */
export async function deleteChatIfNoPendingTurn(
  dbInstance: ChatDatabaseInstance,
  chatId: string,
): Promise<{ deleted: boolean; deletedEmbedIds: string[] }> {
  return deleteChatConditionally(dbInstance, chatId, false);
}

/** A stale empty-editor cleanup must never delete a newly committed first turn. */
export async function deleteDraftOnlyChat(
  dbInstance: ChatDatabaseInstance,
  chatId: string,
): Promise<{ deleted: boolean; deletedEmbedIds: string[] }> {
  return deleteChatConditionally(dbInstance, chatId, true);
}

async function deleteChatConditionally(
  dbInstance: ChatDatabaseInstance,
  chatId: string,
  requireDraftOnly: boolean,
): Promise<{ deleted: boolean; deletedEmbedIds: string[] }> {
  await dbInstance.init();
  const hashedChatId = await computeSHA256(chatId);
  // Crypto is asynchronous. Prepare hashed embed IDs before opening the write
  // transaction, then verify these exact heads again under its store lock.
  const candidateTx = await dbInstance.getTransaction(EMBEDS_STORE_NAME, "readonly");
  const candidateRequest = candidateTx.objectStore(EMBEDS_STORE_NAME)
    .index("hashed_chat_id").getAll(hashedChatId, MAX_INFERRED_DELETE_EMBEDS + 1);
  const candidates = await new Promise<Array<Record<string, unknown>>>((resolve, reject) => {
    candidateRequest.onsuccess = () => resolve(candidateRequest.result as Array<Record<string, unknown>>);
    candidateRequest.onerror = () => reject(candidateRequest.error);
  });
  if (candidates.length > MAX_INFERRED_DELETE_EMBEDS ||
      candidates.some((head) => typeof head.embed_id !== "string" ||
        typeof head.contentRef !== "string")) {
    return { deleted: false, deletedEmbedIds: [] };
  }
  const candidatesByRef = new Map<string, { head: Record<string, unknown>; hash: string }>();
  for (const head of candidates) {
    candidatesByRef.set(head.contentRef as string, {
      head, hash: await computeSHA256(head.embed_id as string),
    });
  }

  const tx = await dbInstance.getTransaction(
    [dbInstance.CHATS_STORE_NAME, MESSAGES_STORE_NAME, EMBEDS_STORE_NAME, EMBED_KEYS_STORE_NAME],
    "readwrite",
  );
  const messages = tx.objectStore(MESSAGES_STORE_NAME);
  const chats = tx.objectStore(dbInstance.CHATS_STORE_NAME);
  const embeds = tx.objectStore(EMBEDS_STORE_NAME);
  const keys = tx.objectStore(EMBED_KEYS_STORE_NAME);
  return new Promise((resolve, reject) => {
    let deleted = false;
    let scanned = 0;
    const deletedEmbedIds: string[] = [];
    const headsToDelete: string[] = [];
    const keysToDelete: string[] = [];
    tx.oncomplete = () => {
      if (deleted) invalidateRecentChatWindow(chatId, 'delete');
      resolve({ deleted, deletedEmbedIds });
    };
    tx.onerror = () => reject(tx.error ?? new Error("Inferred chat deletion failed"));
    tx.onabort = () => reject(tx.error ?? new Error("Inferred chat deletion aborted"));

    const pending = messages.index("pending_turn_created_at_message_id").openCursor(
      IDBKeyRange.bound([1, 0, ""], [1, Number.MAX_SAFE_INTEGER, "\uffff"]),
    );
    pending.onerror = () => tx.abort();
    pending.onsuccess = () => {
      const cursor = pending.result;
      if (!cursor) {
        if (requireDraftOnly) verifyDraftShell();
        else verifyHeads();
        return;
      }
      const row = cursor.value as Message & Record<string, unknown>;
      if (row.chat_id === chatId &&
          typeof row.pending_encrypted_turn_preflight_v1 === "string" &&
          row.pending_encrypted_turn_preflight_v1.length > 0) return;
      if (++scanned >= MAX_INFERRED_DELETE_PENDING_PROBE) return;
      cursor.continue();
    };

    function verifyDraftShell(): void {
      const request = chats.get(chatId);
      request.onerror = () => tx.abort();
      request.onsuccess = () => {
        const chat = request.result as Chat | undefined;
        if (!isDraftOnlyChatSurface(chat, true)) return;
        // Header and first-message writes are separate transactions. Either
        // one establishes that an empty-editor cleanup no longer owns the row.
        const messageRequest = messages.index("chat_id").openCursor(IDBKeyRange.only(chatId));
        messageRequest.onerror = () => tx.abort();
        messageRequest.onsuccess = () => {
          if (!messageRequest.result) verifyHeads();
        };
      };
    }

    function verifyHeads(): void {
      const request = embeds.index("hashed_chat_id")
        .getAll(hashedChatId, MAX_INFERRED_DELETE_EMBEDS + 1);
      request.onerror = () => tx.abort();
      request.onsuccess = () => {
        const current = request.result as Array<Record<string, unknown>>;
        if (current.length !== candidatesByRef.size) return;
        for (const head of current) {
          const prepared = candidatesByRef.get(String(head.contentRef));
          if (!prepared || head.embed_id !== prepared.head.embed_id ||
              head.encrypted_content !== prepared.head.encrypted_content ||
              head.version_number !== prepared.head.version_number ||
              head.hashed_chat_id !== hashedChatId) return;
        }
        inspectKeys(current, 0);
      };
    }

    function inspectKeys(current: Array<Record<string, unknown>>, index: number): void {
      if (index === current.length) { deleteChatAndMessages(); return; }
      const head = current[index];
      const prepared = candidatesByRef.get(String(head.contentRef));
      if (!prepared) return;
      const request = keys.index("hashed_embed_id")
        .getAll(prepared.hash, MAX_INFERRED_DELETE_KEYS_PER_EMBED + 1);
      request.onerror = () => tx.abort();
      request.onsuccess = () => {
        const wrappers = request.result as Array<Record<string, unknown>>;
        if (wrappers.length > MAX_INFERRED_DELETE_KEYS_PER_EMBED ||
            wrappers.some((wrapper) => typeof wrapper.id !== "string")) return;
        const shared = wrappers.some((wrapper) => wrapper.key_type === "chat" &&
          typeof wrapper.hashed_chat_id === "string" &&
          wrapper.hashed_chat_id !== hashedChatId);
        if (shared) {
          for (const wrapper of wrappers) {
            if (wrapper.key_type === "chat" && wrapper.hashed_chat_id === hashedChatId)
              keysToDelete.push(wrapper.id as string);
          }
        } else {
          headsToDelete.push(head.contentRef as string);
          for (const wrapper of wrappers) keysToDelete.push(wrapper.id as string);
          deletedEmbedIds.push(head.embed_id as string);
        }
        inspectKeys(current, index + 1);
      };
    }

    function deleteChatAndMessages(): void {
      for (const contentRef of headsToDelete) embeds.delete(contentRef);
      for (const id of keysToDelete) keys.delete(id);
      chats.delete(chatId);
      const cursorRequest = messages.index("chat_id").openCursor(IDBKeyRange.only(chatId));
      cursorRequest.onerror = () => tx.abort();
      cursorRequest.onsuccess = () => {
        const cursor = cursorRequest.result;
        if (!cursor) { deleted = true; return; }
        cursor.delete();
        cursor.continue();
      };
    }
  });
}

// Maximum candidate keys stored per chat — prevents unbounded IDB growth
const MAX_CANDIDATE_KEYS = 5;

const SHARED_CHAT_KEY_SOURCES = new Set(["share_link", "shared_storage"]);

function isSharedChatKeySource(chatId: string): boolean {
  const provenance = chatKeyManager.getProvenance(chatId);
  return provenance ? SHARED_CHAT_KEY_SOURCES.has(provenance.source) : false;
}

async function unwrapPersistedChatKey(
  teamId: string | null | undefined,
  chatId: string,
  encryptedChatKey: string,
  visibility?: string | null,
): Promise<Uint8Array | null> {
  if (!teamId) return decryptChatKeyWithMasterKey(encryptedChatKey);
  try {
    const { unwrapTeamOrDirectChatKey } = await import("../directChatService");
    return await unwrapTeamOrDirectChatKey(teamId, chatId, encryptedChatKey, visibility);
  } catch (error) {
    console.error(
      `[ChatDatabase] Failed to unwrap Team chat key for team ${teamId}`,
      error,
    );
    return null;
  }
}

async function wrapPersistedChatKey(
  teamId: string | null | undefined,
  chatKey: Uint8Array,
  visibility?: string | null,
): Promise<string | null> {
  if (visibility === 'direct') throw new Error('Direct chat keys must retain their participant envelope');
  return teamId
    ? wrapTeamChatKey(teamId, chatKey)
    : encryptChatKeyWithMasterKey(chatKey);
}

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

/**
 * Append a rejected encrypted_chat_key blob to a chat's candidate_encrypted_keys array in IDB.
 * Deduplicates by value and enforces MAX_CANDIDATE_KEYS (oldest entry dropped when full).
 * Called whenever injectKey() rejects a conflicting key so the blob isn't lost forever.
 */
export async function addCandidateKey(
  dbInstance: ChatDatabaseInstance,
  chatId: string,
  encryptedKeyBlob: string,
): Promise<void> {
  try {
    const chat = await dbInstance.getChat(chatId);
    if (!chat) return;

    const existing = chat.candidate_encrypted_keys ?? [];
    if (existing.includes(encryptedKeyBlob)) return; // already stored

    const updated = [...existing, encryptedKeyBlob].slice(-MAX_CANDIDATE_KEYS);
    // Use a minimal update object — only touch the candidate_encrypted_keys field
    const transaction = await dbInstance.getTransaction(
      dbInstance.CHATS_STORE_NAME,
      "readwrite",
    );
    const store = transaction.objectStore(dbInstance.CHATS_STORE_NAME);
    store.put({ ...chat, candidate_encrypted_keys: updated });
  } catch (err) {
    console.warn(
      `[ChatDatabase] Failed to persist candidate key for chat ${chatId}:`,
      err,
    );
  }
}

/**
 * Extract title from TipTap JSON content (first line of text)
 */
function _extractTitleFromContent(content: TiptapJSON): string {
  if (!content) return "";
  try {
    const firstTextNode = content.content?.[0]?.content?.[0];
    if (
      firstTextNode?.type === "text" &&
      typeof firstTextNode.text === "string"
    ) {
      return (
        firstTextNode.text.slice(0, 50) +
        (firstTextNode.text.length > 50 ? "..." : "")
      );
    }
  } catch (error) {
    console.error("[ChatDatabase] Error extracting title from content:", error);
  }
  return "";
}

// ============================================================================
// CHAT ENCRYPTION/DECRYPTION
// ============================================================================

function isExpectedKeylessDraftOnlySyncChat(chat: Chat, existingChat: Chat | null): boolean {
  // Personal draft ciphertext uses the account master key. A new draft-only
  // shell has no chat key or messages yet; a real chat must retain the guard.
  return !chat.team_id && !chat.chat_visibility &&
    !chat.is_anonymous && !chat.anonymous_encrypted_chat_key &&
    !chat.is_shared && !chat.is_shared_by_others &&
    !chat.encrypted_chat_key && !chat.encrypted_title &&
    chat.messages_v === 0 && (chat.draft_v ?? 0) > 0 &&
    !!chat.encrypted_draft_md && chat.encrypted_draft_md !== "null" &&
    (!existingChat || (
      !existingChat.encrypted_chat_key && !existingChat.encrypted_title &&
      !existingChat.team_id && !existingChat.chat_visibility &&
      existingChat.messages_v === 0
    ));
}

/**
 * Encrypt chat data before storing in IndexedDB
 * EXCEPTION: Public chats (chat_id starting with 'demo-' or 'legal-') are NOT encrypted
 * since they contain public template content that's the same for all users
 *
 * CRITICAL: This function is now async because encryptChatKeyWithMasterKey is async.
 * All callers must await this function to prevent storing Promises in IndexedDB.
 */
export async function encryptChatForStorage(
  dbInstance: ChatDatabaseInstance,
  chat: Chat,
  options?: { isFromSync?: boolean; forceIncomingEncryptedChatKey?: boolean },
): Promise<Chat> {
  // Skip encryption entirely for public chats (demo + legal) - they're public content
  // Add null check to prevent TypeError when chat.chat_id is undefined
  if (
    chat.chat_id &&
    (chat.chat_id.startsWith("demo-") || chat.chat_id.startsWith("legal-"))
  ) {
    console.debug(
      `[ChatDatabase] Skipping encryption for public chat: ${chat.chat_id}`,
    );
    return { ...chat }; // Return as-is without encryption
  }

  const encryptedChat = { ...chat };

  // Title is already encrypted in the chat object (encrypted_title field)
  // No need to encrypt again - just ensure it's properly set
  if (chat.encrypted_title) {
    encryptedChat.encrypted_title = chat.encrypted_title;
  }

  // Icon is already encrypted in the chat object (encrypted_icon field)
  // No need to encrypt again - just ensure it's properly set
  if (chat.encrypted_icon) {
    encryptedChat.encrypted_icon = chat.encrypted_icon;
  }

  // Category is already encrypted in the chat object (encrypted_category field)
  // No need to encrypt again - just ensure it's properly set
  if (chat.encrypted_category) {
    encryptedChat.encrypted_category = chat.encrypted_category;
  }

  // Handle chat-specific encryption key
  // CRITICAL: If chat already has encrypted_chat_key from server, decrypt and cache it
  // Only generate new key if this is a brand new chat without a key
  // Add null check for chat.chat_id to prevent errors
  if (!chat.chat_id) {
    console.error("[ChatDatabase] Cannot encrypt chat - chat_id is undefined");
    return encryptedChat;
  }

  // Step 1: check ChatKeyManager (single source of truth)
  let chatKey = chatKeyManager.getKeySync(chat.chat_id);

  if (!chatKey && chat.is_anonymous && chat.anonymous_encrypted_chat_key) {
    const anonymousKey = await unwrapAnonymousChatKey(chat.anonymous_encrypted_chat_key);
    if (anonymousKey) {
      chatKeyManager.injectKey(chat.chat_id, anonymousKey, "anonymous_session");
      chatKey = anonymousKey;
    }
  }

  // If sync provides a key while a different key is already cached, do not
  // store the incoming key beside locally encrypted fields. The caller must
  // explicitly clear/reload ChatKeyManager before accepting a server key change.
  if (chatKey && chat.encrypted_chat_key) {
    const incomingKey = await unwrapPersistedChatKey(
      chat.team_id,
      chat.chat_id,
      chat.encrypted_chat_key,
      chat.chat_visibility,
    );
    if (incomingKey) {
      if (!chatKeysEqual(chatKey, incomingKey)) {
        const existingChat = await dbInstance.getChat(chat.chat_id);
        if (options?.forceIncomingEncryptedChatKey) {
          if (existingChat?.encrypted_chat_key) {
            await addCandidateKey(
              dbInstance,
              chat.chat_id,
              existingChat.encrypted_chat_key,
            );
          }
          chatKeyManager.injectKey(
            chat.chat_id,
            incomingKey,
            "server_sync",
            true,
          );
          chatKey = incomingKey;
          encryptedChat.encrypted_chat_key = chat.encrypted_chat_key;
          console.warn(
            `[ChatDatabase] Accepting authoritative server encrypted_chat_key for chat ${chat.chat_id}; ` +
              `previous local key was preserved as a candidate`,
          );
        } else {
          addCandidateKey(
            dbInstance,
            chat.chat_id,
            chat.encrypted_chat_key,
          ).catch(() => {});
          encryptedChat.encrypted_chat_key =
            existingChat?.encrypted_chat_key ??
            (await wrapPersistedChatKey(chat.team_id, chatKey, chat.chat_visibility));
          console.warn(
            `[ChatDatabase] Refusing to persist conflicting encrypted_chat_key for chat ${chat.chat_id}; ` +
              `cached key remains authoritative until sync explicitly reloads the server key`,
          );
        }
      }
    } else if (chat.team_id) {
      if (options?.isFromSync) return encryptedChat;
      throw new Error(
        `[ChatDatabase] Cannot save Team chat ${chat.chat_id}: existing Team chat key could not be unwrapped`,
      );
    }
  }

  // Step 2: server-provided encrypted_chat_key on the incoming chat object
  if (!chatKey && chat.encrypted_chat_key) {
    const candidateKey = await unwrapPersistedChatKey(
      chat.team_id,
      chat.chat_id,
      chat.encrypted_chat_key,
      chat.chat_visibility,
    );
    if (candidateKey) {
      const accepted = chatKeyManager.injectKey(
        chat.chat_id,
        candidateKey,
        "master_key",
      );
      if (accepted) {
        chatKey = candidateKey;
        encryptedChat.encrypted_chat_key = chat.encrypted_chat_key;
      }
      // If rejected: save the conflicting blob as a candidate so tryDecryptWithCandidates
      // can recover it later if the local key turns out to be the wrong one.
      if (!accepted && chat.encrypted_chat_key) {
        addCandidateKey(
          dbInstance,
          chat.chat_id,
          chat.encrypted_chat_key,
        ).catch(() => {});
      }
    } else if (chat.team_id) {
      if (options?.isFromSync) return encryptedChat;
      throw new Error(
        `[ChatDatabase] Cannot save Team chat ${chat.chat_id}: incoming Team chat key could not be unwrapped`,
      );
    } else {
      console.error(
        `[ChatDatabase] Failed to decrypt chat key for chat ${chat.chat_id}`,
      );
    }
  }

  // Step 3: IDB integrity check — the chat object may lack the key but IDB already holds it
  let existingChatWithoutKey: Chat | null = null;
  if (!chatKey) {
    const existingChat = await dbInstance.getChat(chat.chat_id);
    existingChatWithoutKey = existingChat;
    if (existingChat?.encrypted_chat_key) {
      chatKey = await unwrapPersistedChatKey(
        existingChat.team_id ?? chat.team_id,
        chat.chat_id,
        existingChat.encrypted_chat_key,
        existingChat.chat_visibility ?? chat.chat_visibility,
      );
      if (chatKey) {
        chatKeyManager.injectKey(chat.chat_id, chatKey, "master_key");
        encryptedChat.encrypted_chat_key = existingChat.encrypted_chat_key;
        console.info(
          `[ChatDatabase] Recovered existing encrypted_chat_key from IDB for chat ${chat.chat_id}`,
        );
      } else if (existingChat.team_id ?? chat.team_id) {
        if (options?.isFromSync) return encryptedChat;
        throw new Error(
          `[ChatDatabase] Cannot save Team chat ${chat.chat_id}: persisted Team chat key could not be unwrapped`,
        );
      }
    }
  }

  // Step 4: genuinely new chat — create key through ChatKeyManager (single source of truth)
  // CRITICAL GUARD: During sync (isFromSync=true), NEVER create a new key for a chat.
  // Creating a new random key for a synced chat overwrites the original key and makes
  // all existing messages permanently undecryptable (the original key is lost).
  // This was the root cause of OPE-314-class decryption failures after logout/login.
  if (!chatKey) {
    if (chat.chat_visibility === 'direct' || chat.encrypted_chat_key?.startsWith('OMDM1.')) {
      throw new Error(`Cannot create or replace the key for direct chat ${chat.chat_id}`);
    }
    if (chat.is_anonymous) {
      throw new Error(
        `[ChatDatabase] Cannot save anonymous chat ${chat.chat_id}: anonymous chat key is unavailable`,
      );
    }
    if (options?.isFromSync) {
      if (!isExpectedKeylessDraftOnlySyncChat(chat, existingChatWithoutKey)) {
        console.error(
          `[ChatDatabase] ⚠️ SYNC GUARD: No chat key available for synced chat ${chat.chat_id}. ` +
            `Refusing to create a new key — this would corrupt existing messages. ` +
            `The chat will be stored without a key; it will be decryptable once the ` +
            `correct key is loaded via receiveKeyFromServer().`,
        );
      }
      // Store the chat without a key — it will be populated later when
      // the correct key arrives via Phase 1a receiveKeyFromServer() or
      // a subsequent sync that includes encrypted_chat_key.
      return encryptedChat;
    }
    console.log(
      `[ChatDatabase] Generating NEW chat key for chat ${chat.chat_id} (new chat creation)`,
    );
    if (chat.team_id) {
      chatKey = chatKeyManager.createKeyForNewChat(chat.chat_id);
      encryptedChat.encrypted_chat_key = await wrapTeamChatKey(
        chat.team_id,
        chatKey,
      );
    } else {
      const result = await chatKeyManager.createAndPersistKeyLocked(chat.chat_id);
      chatKey = result.chatKey;
      encryptedChat.encrypted_chat_key = result.encryptedChatKey;
    }
  }

  // Ensure encrypted_chat_key is present in the stored object
  if (
    !encryptedChat.encrypted_chat_key &&
    !chat.is_anonymous &&
    !isSharedChatKeySource(chat.chat_id)
  ) {
    const encryptedChatKey = await wrapPersistedChatKey(chat.team_id, chatKey, chat.chat_visibility);
    if (encryptedChatKey) {
      encryptedChat.encrypted_chat_key = encryptedChatKey;
    } else {
      console.error(
        `[ChatDatabase] ❌ Failed to encrypt chat key for chat ${chat.chat_id} — master key may be missing`,
      );
    }
  }

  if (chat.is_anonymous) {
    encryptedChat.encrypted_chat_key = null;
  }

  // Stamp key_version and key_fingerprint for decryption-failure diagnosis and future key rotation.
  // key_version starts at 1 for new chats; existing chats without this field read as null (version unknown).
  if (!encryptedChat.key_version) {
    encryptedChat.key_version = 1;
  }
  encryptedChat.key_fingerprint = computeKeyFingerprint(chatKey);

  // TODO: Add encryption for new fields when implemented:
  // - encrypted_chat_summary (from post-processing)
  // - encrypted_chat_tags (from post-processing)
  // - encrypted_follow_up_request_suggestions (from post-processing)

  // Note: encrypted_draft_md is already encrypted by the draft service, so we don't encrypt it again

  return encryptedChat;
}

/**
 * Decrypt chat data after loading from IndexedDB
 * EXCEPTION: Public chats (chat_id starting with 'demo-' or 'legal-') are NOT decrypted
 * since they're stored as plaintext (public template content)
 */
export async function decryptChatFromStorage(
  dbInstance: ChatDatabaseInstance,
  chat: Chat,
): Promise<Chat> {
  // Skip decryption entirely for public chats (demo + legal) - they're stored as plaintext
  if (chat.chat_id.startsWith("demo-") || chat.chat_id.startsWith("legal-")) {
    console.debug(
      `[ChatDatabase] Skipping decryption for public chat: ${chat.chat_id}`,
    );
    return { ...chat }; // Return as-is without decryption
  }

  const decryptedChat = { ...chat };

  // Ensure required fields have default values if they're undefined
  // This handles cases where older database records might not have these fields
  // Note: Version fields should never be undefined since addChat() ensures defaults
  // But keep fallbacks for safety (e.g., old data from before the fix, or direct DB manipulation)
  if (decryptedChat.messages_v === undefined) {
    decryptedChat.messages_v = 0;
  }
  if (decryptedChat.title_v === undefined) {
    decryptedChat.title_v = 0;
  }
  if (decryptedChat.draft_v === undefined) {
    decryptedChat.draft_v = 0;
  }

  // Title decryption is handled by the UI layer when needed
  // The database layer just stores encrypted titles
  // No need to decrypt here as the UI will handle decryption on demand

  // Handle decryption of new encrypted fields with chat-specific key
  if (chat.is_anonymous && chat.anonymous_encrypted_chat_key) {
    const anonymousKey = await unwrapAnonymousChatKey(chat.anonymous_encrypted_chat_key);
    if (anonymousKey) {
      chatKeyManager.injectKey(chat.chat_id, anonymousKey, "anonymous_session");
    } else {
      chatKeyManager.removeKey(chat.chat_id);
    }
  }

  // Handle decryption of new encrypted fields with chat-specific key
  if (chat.encrypted_chat_key) {
    // CRITICAL: Always clear is_hidden flags first to ensure fresh state
    // This prevents chats encrypted with a different code from showing up when unlocked with a new code
    decryptedChat.is_hidden = false;
    decryptedChat.is_hidden_candidate = false;

    if (chat.team_id) {
      try {
        const { unwrapTeamOrDirectChatKey } = await import("../directChatService");
        const teamChatKey = await unwrapTeamOrDirectChatKey(
          chat.team_id,
          chat.chat_id,
          chat.encrypted_chat_key,
          chat.chat_visibility,
        );
        chatKeyManager.injectKey(
          chat.chat_id,
          teamChatKey,
          "server_sync",
        );
      } catch (error) {
        // A temporarily unavailable Team key must not erase a valid key that was
        // already created or loaded in this tab. The write guard will fail closed.
        console.error(
          `[ChatDatabase] Failed to unwrap Team chat key while reading chat ${chat.chat_id}`,
          error,
        );
      }
    } else {
      // Always check the decryption path to determine if chat is hidden, even if we have a cached key
      // This ensures hidden chats are properly identified and filtered
      const { hiddenChatService } = await import("../hiddenChatService");
      const result = await hiddenChatService.tryDecryptChatKey(
        chat.encrypted_chat_key,
      );

      // If normal decryption fails, mark as a hidden candidate for UI filtering.
      // This keeps locked hidden chats out of the main list without a DB flag.
      if (result.isHiddenCandidate) {
        decryptedChat.is_hidden_candidate = true;
      }

      if (result.chatKey) {
        // Inject into ChatKeyManager (single source of truth)
        chatKeyManager.injectKey(chat.chat_id, result.chatKey, "master_key");
        if (result.isHidden) {
          decryptedChat.is_hidden = true;
        } else {
          decryptedChat.is_hidden = false;
        }
      } else {
        // Both decryption paths failed - could be corrupted or a locked hidden chat
        console.debug(
          `[ChatDatabase] Failed to decrypt chat key for chat ${chat.chat_id} (both normal and hidden paths failed)`,
        );
        // Clear any stale key since decryption failed
        chatKeyManager.removeKey(chat.chat_id);
        // is_hidden is already false from the initial clear above
      }
    }

    // Note: We don't decrypt icon and category here because they should be decrypted
    // on-demand by the UI layer when needed, not stored as part of the Chat object.
    // The Chat object should only contain the encrypted fields for zero-knowledge architecture.

    // TODO: Add decryption for other new fields when implemented:
    // - encrypted_chat_summary -> decrypted chat_summary
    // - encrypted_chat_tags -> decrypted chat_tags
    // - encrypted_follow_up_request_suggestions -> decrypted follow_up_request_suggestions
  }

  // Note: encrypted_draft_md and encrypted_draft_preview are already encrypted by the draft service
  // and should be decrypted by the draft service or cache. The database just stores them as-is.
  // Make sure these fields are preserved in the returned chat object.

  return decryptedChat;
}

// ============================================================================
// CHAT CRUD OPERATIONS
// ============================================================================

const CHAT_TRANSACTION_TIMEOUT_MS = 10_000;

/**
 * Add or update a chat in the database
 */
export async function addChat(
  dbInstance: ChatDatabaseInstance,
  chat: Chat,
  transaction?: IDBTransaction,
  options?: { isFromSync?: boolean; forceIncomingEncryptedChatKey?: boolean; writeGuard?: () => void },
): Promise<void> {
  console.debug(
    `[ChatDatabase] addChat called for chat ${chat.chat_id} with transaction: ${!!transaction}`,
  );

  // CRITICAL: During forced logout (missing master key), only allow adding public or anonymous chats.
  // Refuse to save encrypted user chats since they cannot be decrypted later without the master key.
  if (
    get(forcedLogoutInProgress) &&
    !isPublicChat(chat.chat_id ?? "") &&
    !isAnonymousChatId(chat.chat_id)
  ) {
    console.error(
      `[ChatDatabase] Refusing to addChat during forced logout - chat ${chat.chat_id}`,
    );
    throw new Error("Cannot create encrypted chat during forced logout");
  }

  if (!dbInstance.db || get(isLoggingOut)) {
    await dbInstance.init();
  }

  // CRITICAL FIX: Ensure draft_v always defaults to 0 if undefined
  // This prevents warnings during decryption and ensures consistency
  // CRITICAL FIX: Ensure last_edited_overall_timestamp exists for getAllChats index query
  // If missing, fall back to updated_at (which always exists from server)
  const chatWithDefaults: Chat = {
    ...chat,
    draft_v: chat.draft_v ?? 0, // Default to 0 if undefined
    title_v: chat.title_v ?? 0, // Also ensure title_v has a default
    messages_v: chat.messages_v ?? 0, // And messages_v
    // Fall back through updated_at → created_at before using Date.now().
    // Date.now() would stamp a new chat with the current time and push it to the
    // top of the sort order — only acceptable for genuinely brand-new chats that
    // have no timestamps at all yet.
    last_edited_overall_timestamp:
      chat.last_edited_overall_timestamp ??
      chat.updated_at ??
      chat.created_at ??
      Math.floor(Date.now() / 1000),
  };

  // CRITICAL FIX: For external transactions, we need to do async work BEFORE checking transaction state
  // because IndexedDB transactions auto-commit when there are no pending operations
  // If we do async work after receiving the transaction, it might finish before we use it
  const usesExternalTransaction = !!transaction;

  // CRITICAL FIX: Do async encryption work BEFORE using the transaction
  // This ensures the transaction is still active when we try to use it
  const chatToSave = await encryptChatForStorage(
    dbInstance,
    chatWithDefaults,
    options,
  );
  delete chatToSave.messages;

  return new Promise<void>((resolve, reject) => {
    let activeTransaction: IDBTransaction | null = transaction ?? null;
    let ownsActiveTransaction = false;
    let settled = false;

    function resolveOnce() {
      if (settled) return;
      settled = true;
      clearTimeout(transactionTimeout);
      resolve();
    }
    function rejectOnce(error: unknown) {
      if (settled) return;
      settled = true;
      clearTimeout(transactionTimeout);
      reject(error);
    }
    const transactionTimeout = setTimeout(() => {
      const timeoutError = new Error(
        `IndexedDB transaction timed out while saving chat ${chatToSave.chat_id}`,
      );
      rejectOnce(timeoutError);
      if (activeTransaction && ownsActiveTransaction) {
        try {
          activeTransaction.abort();
        } catch {
          // The transaction may have completed just before the timeout fired.
        }
      }
    }, CHAT_TRANSACTION_TIMEOUT_MS);

    (async () => {
      // CRITICAL FIX: Check if external transaction is still active before using it
      if (usesExternalTransaction && transaction) {
        // Check transaction state - if it's finished, we need to create a new one
        try {
          // Try to access the transaction's mode - if it throws, the transaction is finished
          const mode = transaction.mode;
          if (!mode) throw new Error("Transaction mode is undefined");

          // Also check if transaction is still active by checking error property
          if (transaction.error !== null) {
            throw new Error(`Transaction has error: ${transaction.error}`);
          }
        } catch (e) {
          console.warn(
            `[ChatDatabase] External transaction is no longer active for chat ${chatToSave.chat_id}, creating new transaction:`,
            e,
          );
          // Transaction is finished, create a new one
          const newTransaction = await dbInstance.getTransaction(
            dbInstance.CHATS_STORE_NAME,
            "readwrite",
          );
          if (settled) return;
          activeTransaction = newTransaction;
          ownsActiveTransaction = true;

          // CRITICAL FIX: Set up transaction handlers BEFORE queuing any operations
          newTransaction.oncomplete = () => {
            console.debug(
              "[ChatDatabase] ✅ New transaction for addChat completed successfully for chat:",
              chatToSave.chat_id,
            );
            resolveOnce();
          };

          newTransaction.onerror = () => {
            console.error(
              "[ChatDatabase] ❌ New transaction for addChat failed for chat:",
              chatToSave.chat_id,
              "Error:",
              newTransaction.error,
            );
            rejectOnce(newTransaction.error);
          };

          newTransaction.onabort = () => {
            console.error(
              "[ChatDatabase] ❌ New transaction for addChat aborted for chat:",
              chatToSave.chat_id,
            );
            rejectOnce(new Error("Transaction aborted"));
          };

          const store = newTransaction.objectStore(dbInstance.CHATS_STORE_NAME);
          options?.writeGuard?.();
          const request = store.put(chatToSave);

          request.onsuccess = () => {
            console.debug(
              "[ChatDatabase] Chat put request successful (queued):",
              chatToSave.chat_id,
              "Versions:",
              {
                m: chatToSave.messages_v,
                t: chatToSave.title_v,
                d: chatToSave.draft_v,
              },
            );
            // resolve() is called in oncomplete handler above
          };

          request.onerror = () => {
            console.error(
              "[ChatDatabase] Error in chat store.put operation:",
              request.error,
            );
            // Transaction will abort and onerror/onabort will be called
          };

          return;
        }
      }

      const currentTransaction =
        transaction ||
        (await dbInstance.getTransaction(
          dbInstance.CHATS_STORE_NAME,
          "readwrite",
        ));
      if (settled) return;
      activeTransaction = currentTransaction;
      ownsActiveTransaction = !usesExternalTransaction;

      console.debug(
        `[ChatDatabase] Using ${usesExternalTransaction ? "external" : "internal"} transaction for chat ${chatToSave.chat_id}`,
      );

      // CRITICAL FIX: Check transaction state one more time right before using it
      try {
        // CRITICAL FIX: Set up transaction handlers BEFORE queuing any operations
        // This prevents a race condition where the transaction auto-commits before we set handlers
        if (!usesExternalTransaction) {
          currentTransaction.oncomplete = () => {
            console.debug(
              "[ChatDatabase] ✅ Transaction for addChat completed successfully for chat:",
              chatToSave.chat_id,
            );
            resolveOnce();
          };
          currentTransaction.onerror = () => {
            const error = currentTransaction.error;
            const errorName =
              error instanceof DOMException ? error.name : "Unknown";
            const errorMessage = error?.message || "Unknown error";
            console.error(
              `[ChatDatabase] ❌ Transaction for addChat failed for chat: ${chatToSave.chat_id}, Error: ${errorName} - ${errorMessage}`,
              error,
            );
            rejectOnce(error || new Error("Transaction error"));
          };
          currentTransaction.onabort = () => {
            const error = currentTransaction.error;
            const errorName =
              error instanceof DOMException ? error.name : "Unknown";
            const errorMessage = error?.message || "Unknown reason";
            console.error(
              `[ChatDatabase] ❌ Transaction for addChat aborted for chat: ${chatToSave.chat_id}, Error: ${errorName} - ${errorMessage}`,
              error,
            );

            // Check for QuotaExceededError - this is critical and should be logged prominently
            if (
              error instanceof DOMException &&
              error.name === "QuotaExceededError"
            ) {
              console.error(
                `[ChatDatabase] ❌❌❌ CRITICAL: QuotaExceededError when saving chat ${chatToSave.chat_id}! IndexedDB storage quota exceeded!`,
              );
            }

            rejectOnce(
              error || new Error(`Transaction aborted: ${errorMessage}`),
            );
          };
        }

        const store = currentTransaction.objectStore(
          dbInstance.CHATS_STORE_NAME,
        );
        options?.writeGuard?.();
        const request = store.put(chatToSave);

        console.debug(
          `[ChatDatabase] IndexedDB put request initiated for chat ${chatToSave.chat_id}`,
        );

        request.onsuccess = () => {
          console.debug(
            "[ChatDatabase] Chat put request successful (queued):",
            chatToSave.chat_id,
            "Versions:",
            {
              m: chatToSave.messages_v,
              t: chatToSave.title_v,
              d: chatToSave.draft_v,
            },
          );
          if (usesExternalTransaction) {
            console.debug(
              `[ChatDatabase] External transaction - operation queued for chat ${chatToSave.chat_id}`,
            );
            // CRITICAL FIX: Don't resolve yet! The transaction might not be committed.
            // The calling code should wait for transaction.oncomplete
            resolveOnce(); // Resolve to indicate the operation was queued successfully
          }
          // For internal transactions, resolve() is called in oncomplete handler above
        };
        request.onerror = () => {
          const error = request.error;
          const errorName =
            error instanceof DOMException ? error.name : "Unknown";
          const errorMessage = error?.message || "Unknown error";
          console.error(
            `[ChatDatabase] ❌ Error in chat store.put operation for ${chatToSave.chat_id}: ${errorName} - ${errorMessage}`,
            error,
          );

          // Check for QuotaExceededError - this is critical
          if (
            error instanceof DOMException &&
            error.name === "QuotaExceededError"
          ) {
            console.error(
              `[ChatDatabase] ❌❌❌ CRITICAL: QuotaExceededError when saving chat ${chatToSave.chat_id}! IndexedDB storage quota exceeded!`,
            );
          }

          rejectOnce(error); // This will also cause the transaction to abort if not handled
        };
      } catch (error) {
        // Transaction is no longer active (InvalidStateError or similar)
        const err = error as { name?: string; message?: string };
        if (
          err?.name === "InvalidStateError" ||
          err?.message?.includes("transaction")
        ) {
          console.debug(
            `[ChatDatabase] Transaction expired for chat ${chatToSave.chat_id}, retrying with new transaction`,
          );
          // Create a new transaction and retry
          try {
            const newTransaction = await dbInstance.getTransaction(
              dbInstance.CHATS_STORE_NAME,
              "readwrite",
            );
            if (settled) return;
            activeTransaction = newTransaction;
            ownsActiveTransaction = true;

            // CRITICAL FIX: Set up transaction handlers BEFORE queuing any operations
            newTransaction.oncomplete = () => {
              console.debug(
                "[ChatDatabase] ✅ New transaction for addChat completed successfully for chat:",
                chatToSave.chat_id,
              );
              resolveOnce();
            };

            newTransaction.onerror = () => {
              console.error(
                "[ChatDatabase] ❌ New transaction for addChat failed for chat:",
                chatToSave.chat_id,
                "Error:",
                newTransaction.error,
              );
              rejectOnce(newTransaction.error);
            };

            newTransaction.onabort = () => {
              console.error(
                "[ChatDatabase] ❌ New transaction for addChat aborted for chat:",
                chatToSave.chat_id,
              );
              rejectOnce(new Error("Transaction aborted"));
            };

            const store = newTransaction.objectStore(
              dbInstance.CHATS_STORE_NAME,
            );
            const request = store.put(chatToSave);

            request.onsuccess = () => {
              console.debug(
                "[ChatDatabase] Chat put request successful with new transaction (queued):",
                chatToSave.chat_id,
              );
              // resolve() is called in oncomplete handler above
            };

            request.onerror = () => {
              console.error(
                "[ChatDatabase] Error in chat store.put operation with new transaction:",
                request.error,
              );
              // Transaction will abort and onerror/onabort will be called
            };
          } catch (retryError) {
            console.error(
              `[ChatDatabase] Failed to create new transaction for chat ${chatToSave.chat_id}:`,
              retryError,
            );
            rejectOnce(retryError);
          }
        } else {
          // Some other error - rethrow it
          console.error(
            `[ChatDatabase] Unexpected error in addChat for chat ${chatToSave.chat_id}:`,
            error,
          );
          rejectOnce(error);
        }
      }
    })().catch(rejectOnce);
  });
}

/**
 * Get all chats from the database, sorted by last_edited_overall_timestamp (newest first)
 */
export async function getAllChats(
  dbInstance: ChatDatabaseInstance,
  transaction?: IDBTransaction,
  options?: { limit?: number },
): Promise<Chat[]> {
  const limit = options?.limit;
  console.debug(
    `[ChatDatabase] getAllChats called with transaction: ${!!transaction}, limit: ${limit ?? "none"}`,
  );

  // CRITICAL: During forced logout or active logout, skip reading encrypted chats from IDB.
  // Without this guard, an in-flight getAllChats call during the logout transition reads all
  // encrypted chats, fails to decrypt them (keys cleared), and caches { title: null } entries
  // in chatMetadataCache — which are then served after re-login, causing "Untitled chat".
  // This is consistent with getChat() which already has this guard (line ~741).
  if (get(forcedLogoutInProgress) || get(isLoggingOut)) {
    console.debug(
      "[ChatDatabase] Skipping getAllChats during logout — returning empty array",
    );
    return [];
  }
  await dbInstance.init();
  return new Promise((resolve, reject) => {
    const execute = async () => {
      try {
        const currentTransaction =
          transaction ||
          (await dbInstance.getTransaction(
            dbInstance.CHATS_STORE_NAME,
            "readonly",
          ));
        const store = currentTransaction.objectStore(
          dbInstance.CHATS_STORE_NAME,
        );
        const index = store.index("last_edited_overall_timestamp");
        const request = index.openCursor(null, "prev");
        const rawChats: Chat[] = []; // Collect raw chat data synchronously
        let count = 0;

        request.onsuccess = () => {
          const cursor = request.result;
          if (cursor) {
            // Collect raw chat data synchronously (transaction must stay active)
            // Stop early if a limit is specified and reached
            if (limit !== undefined && count >= limit) {
              // Trigger oncomplete by not advancing the cursor — we're done
              // We need to manually resolve since we won't hit the natural end
              currentTransaction.oncomplete = async () => {
                const decryptedChats: Chat[] = [];
                for (const rawChat of rawChats) {
                  try {
                    const decryptedChat = await decryptChatFromStorage(
                      dbInstance,
                      rawChat,
                    );
                    decryptedChats.push(decryptedChat);
                  } catch (error) {
                    console.error(
                      `[ChatDatabase] Error decrypting chat ${rawChat.chat_id}:`,
                      error,
                    );
                    decryptedChats.push(rawChat as Chat);
                  }
                }
                console.debug(
                  `[ChatDatabase] Retrieved ${decryptedChats.length} chats from database (limited to ${limit})`,
                );
                resolve(decryptedChats);
              };
              // Don't call cursor.continue() — this lets the transaction complete naturally
              return;
            }
            const chatData = { ...cursor.value } as Chat;
            delete chatData.messages;
            rawChats.push(chatData);
            count++;
            cursor.continue();
          } else {
            // All cursors processed, now decrypt all chats after transaction completes
            // This ensures the transaction doesn't finish while we're still using the cursor
            currentTransaction.oncomplete = async () => {
              // Decrypt all chats after transaction completes
              const decryptedChats: Chat[] = [];
              for (const rawChat of rawChats) {
                try {
                  const decryptedChat = await decryptChatFromStorage(
                    dbInstance,
                    rawChat,
                  );
                  decryptedChats.push(decryptedChat);
                } catch (error) {
                  console.error(
                    `[ChatDatabase] Error decrypting chat ${rawChat.chat_id}:`,
                    error,
                  );
                  // Still include the chat even if decryption fails (with encrypted data)
                  decryptedChats.push(rawChat as Chat);
                }
              }
              console.debug(
                `[ChatDatabase] Retrieved ${decryptedChats.length} chats from database`,
              );
              resolve(decryptedChats);
            };
          }
        };
        request.onerror = () => {
          console.error("[ChatDatabase] Error getting chats:", request.error);
          reject(request.error);
        };
        // Note: oncomplete handler is set inside request.onsuccess to handle decryption
        // Only set error handler if we're not using an external transaction
        if (!transaction) {
          currentTransaction.onerror = () => {
            console.error(
              `[ChatDatabase] getAllChats transaction failed:`,
              currentTransaction.error,
            );
            reject(currentTransaction.error);
          };
        }
      } catch (e) {
        reject(e);
      }
    };
    execute();
  });
}

/**
 * Get sub-chats for one parent without decrypting every chat in the database.
 * This is intentionally separate from getAllChats() because message-level
 * preview rendering can call it during sync bursts.
 */
export async function getSubChatsForParent(
  dbInstance: ChatDatabaseInstance,
  parentChatId: string,
): Promise<Chat[]> {
  if (get(forcedLogoutInProgress) || get(isLoggingOut)) {
    console.debug(
      "[ChatDatabase] Skipping getSubChatsForParent during logout - returning empty array",
    );
    return [];
  }

  await dbInstance.init();
  return new Promise((resolve, reject) => {
    const execute = async () => {
      try {
        const transaction = await dbInstance.getTransaction(
          dbInstance.CHATS_STORE_NAME,
          "readonly",
        );
        const store = transaction.objectStore(dbInstance.CHATS_STORE_NAME);
        const request = store.openCursor();
        const rawSubChats: Chat[] = [];

        request.onsuccess = () => {
          const cursor = request.result;
          if (cursor) {
            const chatData = { ...cursor.value } as Chat;
            if (chatData.parent_id === parentChatId) {
              delete chatData.messages;
              rawSubChats.push(chatData);
            }
            cursor.continue();
            return;
          }

          transaction.oncomplete = async () => {
            const decryptedChats: Chat[] = [];
            for (const rawChat of rawSubChats) {
              try {
                decryptedChats.push(
                  await decryptChatFromStorage(dbInstance, rawChat),
                );
              } catch (error) {
                console.error(
                  `[ChatDatabase] Error decrypting sub-chat ${rawChat.chat_id}:`,
                  error,
                );
                decryptedChats.push(rawChat);
              }
            }
            resolve(decryptedChats);
          };
        };

        request.onerror = () => {
          console.error("[ChatDatabase] Error getting sub-chats:", request.error);
          reject(request.error);
        };

        transaction.onerror = () => {
          console.error(
            "[ChatDatabase] getSubChatsForParent transaction failed:",
            transaction.error,
          );
          reject(transaction.error);
        };
      } catch (e) {
        reject(e);
      }
    };
    execute();
  });
}

/**
 * Get a single chat by ID
 */
export async function getChat(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
  transaction?: IDBTransaction,
): Promise<Chat | null> {
  // CRITICAL: During forced logout (missing master key), only allow loading public or anonymous chats.
  // Encrypted user chats cannot be decrypted without the master key, so return null to prevent errors.
  if (
    get(forcedLogoutInProgress) &&
    !isPublicChat(chat_id) &&
    !isAnonymousChatId(chat_id)
  ) {
    console.debug(
      `[ChatDatabase] Skipping getChat for encrypted chat ${chat_id} during forced logout - returning null`,
    );
    return null;
  }

  if (!dbInstance.db || get(isLoggingOut)) {
    await dbInstance.init();
  }
  return new Promise((resolve, reject) => {
    const execute = async () => {
      try {
        const currentTransaction =
          transaction ||
          (await dbInstance.getTransaction(
            dbInstance.CHATS_STORE_NAME,
            "readonly",
          ));
        const store = currentTransaction.objectStore(
          dbInstance.CHATS_STORE_NAME,
        );
        const request = store.get(chat_id);

        request.onsuccess = async () => {
          const chatData = request.result;
          if (chatData) {
            delete chatData.messages; // Ensure messages property is not returned
            try {
              const decryptedChat = await decryptChatFromStorage(
                dbInstance,
                chatData,
              );
              resolve(decryptedChat);
            } catch (e) {
              reject(e);
            }
          } else {
            resolve(null);
          }
        };
        request.onerror = () => {
          console.error(
            `[ChatDatabase] Error getting chat ${chat_id}:`,
            request.error,
          );
          reject(request.error);
        };
      } catch (error) {
        console.error(
          `[ChatDatabase] Error in getChat for chat_id ${chat_id}:`,
          error,
        );
        reject(error);
      }
    };
    execute();
  });
}

/**
 * Get a single chat by ID without decrypting chat-key encrypted metadata.
 *
 * Use this only for encrypted-field update paths that must not depend on the
 * local chat key being available, such as synced draft broadcasts. Most callers
 * should use getChat() so they receive decrypted display metadata.
 */
export async function getRawChat(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
  transaction?: IDBTransaction,
): Promise<Chat | null> {
  if (
    get(forcedLogoutInProgress) &&
    !isPublicChat(chat_id) &&
    !isAnonymousChatId(chat_id)
  ) {
    console.debug(
      `[ChatDatabase] Skipping getRawChat for encrypted chat ${chat_id} during forced logout - returning null`,
    );
    return null;
  }

  if (!dbInstance.db) {
    await dbInstance.init();
  }
  return new Promise((resolve, reject) => {
    const execute = async () => {
      try {
        const currentTransaction =
          transaction ||
          dbInstance.db?.transaction(dbInstance.CHATS_STORE_NAME, "readonly");
        if (!currentTransaction) {
          throw new Error("Database not initialized for raw chat read");
        }
        const store = currentTransaction.objectStore(
          dbInstance.CHATS_STORE_NAME,
        );
        const request = store.get(chat_id);

        request.onsuccess = () => {
          const chatData = request.result;
          if (!chatData) {
            resolve(null);
            return;
          }
          const rawChat = { ...chatData } as Chat;
          delete rawChat.messages;
          resolve(rawChat);
        };
        request.onerror = () => {
          console.error(
            `[ChatDatabase] Error getting raw chat ${chat_id}:`,
            request.error,
          );
          reject(request.error);
        };
      } catch (error) {
        console.error(
          `[ChatDatabase] Error in getRawChat for chat_id ${chat_id}:`,
          error,
        );
        reject(error);
      }
    };
    execute();
  });
}

/** Atomically change a client-only Team draft intent without replacing a newer ACK/chat row. */
export async function setTeamDraftPendingSync(
  dbInstance: ChatDatabaseInstance,
  chatId: string,
  teamId: string,
  pending: "update" | "delete" | undefined,
  writeGuard: () => boolean,
  expected?: { kind: "update" | "delete"; cipher?: string | null; version?: number; clearedDraftVersion?: number },
): Promise<Chat | null> {
  if (get(forcedLogoutInProgress) || get(isLoggingOut) || !writeGuard()) return null;
  await dbInstance.init();
  if (!writeGuard()) return null;
  const transaction = await dbInstance.getTransaction(dbInstance.CHATS_STORE_NAME, "readwrite");
  return new Promise((resolve, reject) => {
    let updated: Chat | null = null;
    transaction.oncomplete = () => resolve(updated);
    transaction.onerror = () => reject(transaction.error ?? new Error("Team draft intent transaction failed"));
    transaction.onabort = () => reject(transaction.error ?? new Error("Team draft intent transaction aborted"));
    const store = transaction.objectStore(dbInstance.CHATS_STORE_NAME);
    const request = store.get(chatId);
    request.onerror = () => reject(request.error ?? new Error("Team draft intent read failed"));
    request.onsuccess = () => {
      const chat = request.result as Chat | undefined;
      if (!chat || chat.team_id !== teamId || !writeGuard()) return;
      if (expected && (chat.team_draft_pending_sync !== expected.kind ||
        (expected.cipher !== undefined && chat.encrypted_draft_md !== expected.cipher) ||
        (expected.version !== undefined && (chat.draft_v ?? 0) !== expected.version))) return;
      updated = { ...chat, team_draft_pending_sync: pending,
        cleared_draft_v: expected?.clearedDraftVersion === undefined
          ? chat.cleared_draft_v
          : Math.max(chat.cleared_draft_v ?? 0, expected.clearedDraftVersion) };
      store.put(updated);
    };
  });
}

/** Draft ciphertext is master-key encrypted; never replace its chat security/header snapshot. */
export type ChatDraftFields = Partial<Pick<Chat,
  "encrypted_draft_md" | "encrypted_draft_preview" | "draft_v" | "cleared_draft_v" |
  "ideabucket" | "ideabucket_processing_window_id" | "updated_at"
>>;

/**
 * Update only draft fields under the same transaction that reads the latest row.
 * A sync broadcast may explicitly seed an absent draft shell. Local edits never
 * recreate a deleted chat. No key recovery, generation or replacement runs here.
 */
export async function saveChatDraftFields(
  dbInstance: ChatDatabaseInstance,
  chatId: string,
  fields: ChatDraftFields,
  missingRow?: Chat,
): Promise<Chat | null> {
  if (get(forcedLogoutInProgress) || get(isLoggingOut)) {
    throw new Error("Cannot write chat draft during logout");
  }
  if (!dbInstance.db) await dbInstance.init();
  const transaction = await dbInstance.getTransaction(dbInstance.CHATS_STORE_NAME, "readwrite");
  return new Promise((resolve, reject) => {
    let saved: Chat | null = null;
    transaction.oncomplete = () => resolve(saved);
    transaction.onerror = () => reject(transaction.error ?? new Error("Draft transaction failed"));
    transaction.onabort = () => reject(transaction.error ?? new Error("Draft transaction aborted"));
    const store = transaction.objectStore(dbInstance.CHATS_STORE_NAME);
    const request = store.get(chatId);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      const current = request.result as Chat | undefined;
      if (!current && !missingRow) return;
      if (missingRow && (missingRow.chat_id !== chatId ||
          (current && (current.team_id ?? null) !== (missingRow.team_id ?? null)))) {
        transaction.abort();
        return;
      }
      const base = current ?? missingRow!;
      // Recheck draft ordering under the write lock, rather than trusting the
      // caller's earlier read while a send or deletion was committing.
      const clearsCurrentDraft = fields.encrypted_draft_md === null && fields.draft_v === 0 &&
        (fields.cleared_draft_v ?? -1) >= (base.draft_v ?? 0);
      if (current && !clearsCurrentDraft && fields.draft_v !== undefined &&
          (fields.draft_v < (current.draft_v ?? 0) ||
            (fields.encrypted_draft_md != null && fields.draft_v <= (current.cleared_draft_v ?? -1)))) {
        saved = current;
        return;
      }
      saved = { ...base };
      for (const key of ["encrypted_draft_md", "encrypted_draft_preview", "draft_v",
        "ideabucket", "ideabucket_processing_window_id"] as const) {
        if (Object.prototype.hasOwnProperty.call(fields, key)) {
          Object.assign(saved, { [key]: fields[key] });
        }
      }
      if (fields.cleared_draft_v !== undefined) saved.cleared_draft_v = Math.max(base.cleared_draft_v ?? 0, fields.cleared_draft_v);
      if (fields.updated_at !== undefined) saved.updated_at = Math.max(base.updated_at ?? 0, fields.updated_at);
      delete saved.messages;
      store.put(saved);
    };
  });
}

/**
 * Write already-encrypted chat metadata without chat-key recovery or generation.
 *
 * This is intentionally narrow: use it for sync payloads whose encrypted fields
 * are already server-authoritative and do not require local chat-key access.
 */
export async function upsertRawChat(
  dbInstance: ChatDatabaseInstance,
  chat: Chat,
  transaction?: IDBTransaction,
): Promise<void> {
  if (
    get(forcedLogoutInProgress) &&
    !isPublicChat(chat.chat_id ?? "") &&
    !isAnonymousChatId(chat.chat_id)
  ) {
    console.error(
      `[ChatDatabase] Refusing to upsertRawChat during forced logout - chat ${chat.chat_id}`,
    );
    throw new Error("Cannot write encrypted chat during forced logout");
  }

  if (!dbInstance.db) {
    await dbInstance.init();
  }
  const chatToSave: Chat = {
    ...chat,
    draft_v: chat.draft_v ?? 0,
    title_v: chat.title_v ?? 0,
    messages_v: chat.messages_v ?? 0,
    last_edited_overall_timestamp:
      chat.last_edited_overall_timestamp ??
      chat.updated_at ??
      chat.created_at ??
      Math.floor(Date.now() / 1000),
  };
  delete chatToSave.messages;

  return new Promise<void>((resolve, reject) => {
    const execute = async () => {
      try {
        const currentTransaction =
          transaction ||
          dbInstance.db?.transaction(dbInstance.CHATS_STORE_NAME, "readwrite");
        if (!currentTransaction) {
          throw new Error("Database not initialized for raw chat write");
        }
        const store = currentTransaction.objectStore(
          dbInstance.CHATS_STORE_NAME,
        );
        const request = store.put(chatToSave);

        request.onsuccess = () => {
          if (transaction) resolve();
        };
        request.onerror = () => {
          console.error(
            `[ChatDatabase] Error in raw chat store.put operation for ${chatToSave.chat_id}:`,
            request.error,
          );
          reject(request.error);
        };

        if (!transaction) {
          currentTransaction.oncomplete = () => resolve();
          currentTransaction.onerror = () => reject(currentTransaction.error);
          currentTransaction.onabort = () =>
            reject(currentTransaction.error ?? new Error("Transaction aborted"));
        }
      } catch (error) {
        console.error(
          `[ChatDatabase] Error in upsertRawChat for chat_id ${chatToSave.chat_id}:`,
          error,
        );
        reject(error);
      }
    };
    execute();
  });
}

/**
 * Delete a chat and all its messages
 * Also cleans up associated embeds (if not shared with other chats)
 */
export async function deleteChat(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
  transaction?: IDBTransaction,
): Promise<{ deletedEmbedIds: string[] }> {
  // The active chat component may be unmounted in another workspace. Fence any
  // in-flight message-window read before the first asynchronous deletion step.
  invalidateRecentChatWindow(chat_id, 'delete');
  await dbInstance.init();
  console.debug(`[ChatDatabase] Deleting chat ${chat_id} and its messages.`);

  // CRITICAL: Clean up embeds associated with this chat
  let deletedEmbedIds: string[] = [];

  // Only perform embed cleanup if NO transaction is provided.
  // If a transaction is provided, we cannot safely await without risking transaction timeout (TransactionInactiveError).
  // The caller of batch operations is responsible for pre-cleaning embeds if needed.
  if (!transaction) {
    // This must happen BEFORE the transaction starts to avoid transaction timeout
    // which happens if we await between transaction creation and first request.
    // Import embedStore dynamically to avoid circular dependencies
    try {
      const { embedStore } = await import("../embedStore");
      deletedEmbedIds = await embedStore.deleteEmbedsForChat(chat_id);
      console.debug(
        `[ChatDatabase] Cleaned up ${deletedEmbedIds.length} embeds for chat ${chat_id}`,
      );
    } catch (embedError) {
      // Log but don't fail the entire deletion - embeds can be orphaned but chat must be deleted
      console.error(
        `[ChatDatabase] Error cleaning up embeds for chat ${chat_id}:`,
        embedError,
      );
    }
  }

  const currentTransaction =
    transaction ||
    (await dbInstance.getTransaction(
      [dbInstance.CHATS_STORE_NAME, MESSAGES_STORE_NAME],
      "readwrite",
    ));
  currentTransaction.addEventListener("complete", () => invalidateRecentChatWindow(chat_id, 'delete'));

  const chatStore = currentTransaction.objectStore(dbInstance.CHATS_STORE_NAME);
  const messagesStore = currentTransaction.objectStore(MESSAGES_STORE_NAME);
  const messagesChatIdIndex = messagesStore.index("chat_id");

  return new Promise((resolve, reject) => {
    // Step 1: Delete the chat entry
    const deleteChatRequest = chatStore.delete(chat_id);

    deleteChatRequest.onsuccess = () => {
      console.debug(
        `[ChatDatabase] Chat entry ${chat_id} deleted from chats store.`,
      );

      // Step 2: Delete all messages for this chat
      const deleteMessagesPromises: Promise<void>[] = [];
      const messagesCursorRequest = messagesChatIdIndex.openCursor(
        IDBKeyRange.only(chat_id),
      );

      messagesCursorRequest.onsuccess = (event) => {
        const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
        if (cursor) {
          // Delete this message
          deleteMessagesPromises.push(
            new Promise((res, rej) => {
              const deleteReq = cursor.delete();
              deleteReq.onsuccess = () => res();
              deleteReq.onerror = () => rej(deleteReq.error);
            }),
          );
          cursor.continue();
        } else {
          // Cursor is done - wait for all delete operations to complete
          console.debug(
            `[ChatDatabase] Found ${deleteMessagesPromises.length} messages to delete for chat ${chat_id}`,
          );
          Promise.all(deleteMessagesPromises)
            .then(() => {
              console.debug(
                `[ChatDatabase] All messages deleted for chat ${chat_id}`,
              );
            })
            .catch((error) => {
              console.error(
                `[ChatDatabase] Error deleting messages for chat ${chat_id}:`,
                error,
              );
              reject(error);
            });
        }
      };

      messagesCursorRequest.onerror = () => {
        console.error(
          `[ChatDatabase] Error opening cursor for messages of chat ${chat_id}:`,
          messagesCursorRequest.error,
        );
        reject(messagesCursorRequest.error);
      };
    };

    deleteChatRequest.onerror = () => {
      console.error(
        `[ChatDatabase] Error deleting chat entry ${chat_id}:`,
        deleteChatRequest.error,
      );
      reject(deleteChatRequest.error);
    };

    // Transaction completion handlers
    if (!transaction) {
      currentTransaction.oncomplete = () => {
        console.debug(
          `[ChatDatabase] Chat ${chat_id} and its messages deleted successfully.`,
        );
        resolve({ deletedEmbedIds });
      };
      currentTransaction.onerror = () => {
        console.error(
          `[ChatDatabase] Error in deleteChat transaction for ${chat_id}:`,
          currentTransaction.error,
        );
        reject(currentTransaction.error);
      };
      currentTransaction.onabort = () => {
        console.error(
          `[ChatDatabase] Transaction aborted for deleteChat ${chat_id}`,
        );
        reject(new Error("Transaction aborted"));
      };
    } else {
      // If part of a larger transaction, let caller handle oncomplete/onerror
      resolve({ deletedEmbedIds });
    }
  });
}

