/**
 * Save a draft for the current user's chat
 */
export async function saveCurrentUserChatDraft(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
  draft_content: string | null,
  draft_preview: string | null = null,
): Promise<Chat | null> {
  await dbInstance.init();
  console.debug(
    "[ChatDatabase] Saving current user's encrypted draft for chat:",
    chat_id,
  );

  try {
    // Get the chat first to check if it exists
    const chat = await getChat(dbInstance, chat_id);
    if (!chat) {
      console.warn(
        `[ChatDatabase] Chat ${chat_id} not found when trying to save draft.`,
      );
      return null;
    }

    const nowTimestamp = Math.floor(Date.now() / 1000);
    const contentChanged = chat.encrypted_draft_md !== draft_content;

    if (contentChanged) {
      chat.draft_v = (chat.draft_v || 0) + 1;
    }
    chat.encrypted_draft_md = draft_content; // Now stores encrypted markdown string
    chat.encrypted_draft_preview = draft_preview; // Store encrypted preview for chat list display
    // CRITICAL: Don't update last_edited_overall_timestamp for drafts
    // Only messages should update this timestamp for proper sorting
    // Chats with drafts will appear at the top via sorting logic, but won't affect message-based sorting
    chat.updated_at = nowTimestamp; // Keep updated_at for internal tracking

    console.debug("[ChatDatabase] Saving draft with preview:", {
      chatId: chat_id,
      hasDraftContent: !!draft_content,
      hasPreview: !!draft_preview,
      previewLength: draft_preview?.length || 0,
      draftVersion: chat.draft_v,
    });

    // Use addChat without external transaction to ensure proper completion
    await addChat(dbInstance, chat);
    console.debug(
      `[ChatDatabase] Successfully saved draft for chat ${chat_id}`,
    );
    return chat;
  } catch (error) {
    console.error(
      `[ChatDatabase] Error in saveCurrentUserChatDraft for chat ${chat_id}:`,
      error,
    );
    throw error;
  }
}

/**
 * Create a new chat with a draft
 * NOTE: This function generates a NEW random UUID for the chat.
 * If you need to create a chat with a specific ID, use addChat() directly instead.
 */
export async function createNewChatWithCurrentUserDraft(
  dbInstance: ChatDatabaseInstance,
  draft_content: string,
  draft_preview: string | null = null,
  team_id: string | null = null,
): Promise<Chat> {
  // Log stack trace to help debug duplicate chat creation issues
  console.debug(
    `[ChatDatabase] createNewChatWithCurrentUserDraft called with draft_content length: ${draft_content?.length}, draft_preview length: ${draft_preview?.length}`,
  );
  console.debug(
    "[ChatDatabase] createNewChatWithCurrentUserDraft caller stack:",
    new Error().stack?.split("\n").slice(1, 5).join("\n"),
  );

  await dbInstance.init();
  const nowTimestamp = Math.floor(Date.now() / 1000);
  const newChatId = crypto.randomUUID();
  console.info(
    `[ChatDatabase] Creating NEW chat ${newChatId} with current user's draft (generates random UUID)`,
  );

  // Get current user ID to ensure ownership is recorded
  const { userDB } = await import("../userDB");
  const profile = await userDB.getUserProfile();
  const currentUserId = profile?.user_id;

  const chatToCreate: Chat = {
    chat_id: newChatId,
    team_id,
    team_chat_pending_commit: !!team_id,
    user_id: currentUserId || undefined,
    encrypted_title: null,
    messages_v: 0,
    title_v: 0,
    draft_v: 1, // Initial draft version
    encrypted_draft_md: draft_content,
    encrypted_draft_preview: draft_preview,
    last_edited_overall_timestamp: nowTimestamp,
    unread_count: 0,
    created_at: nowTimestamp,
    updated_at: nowTimestamp,
  };

  console.debug("[ChatDatabase] Creating new chat with draft preview:", {
    chatId: newChatId,
    hasDraftContent: !!draft_content,
    hasPreview: !!draft_preview,
    previewLength: draft_preview?.length || 0,
    hasEncryptedTitle: !!chatToCreate.encrypted_title,
    draftContentLength: draft_content?.length || 0,
    draftPreviewLength: draft_preview?.length || 0,
  });

  try {
    console.debug(
      `[ChatDatabase] About to call addChat for new chat ${newChatId}`,
    );
    // Use addChat without external transaction to ensure proper completion
    await addChat(dbInstance, chatToCreate);
    console.debug(
      `[ChatDatabase] Successfully created new chat ${newChatId} with draft`,
    );

    // Verify the chat was actually saved by trying to retrieve it
    console.debug(
      `[ChatDatabase] Verifying chat ${newChatId} was saved by retrieving it...`,
    );
    const verificationChat = await getChat(dbInstance, newChatId);
    console.debug(`[ChatDatabase] Verification result:`, {
      chatId: newChatId,
      found: !!verificationChat,
      hasEncryptedDraftMd: !!verificationChat?.encrypted_draft_md,
      hasEncryptedDraftPreview: !!verificationChat?.encrypted_draft_preview,
      draftVersion: verificationChat?.draft_v,
    });

    return chatToCreate;
  } catch (error) {
    console.error(
      `[ChatDatabase] Error in createNewChatWithCurrentUserDraft for chat ${newChatId}:`,
      error,
    );
    throw error;
  }
}

/**
 * Clear a draft from a chat
 * NOTE: This function does NOT update last_edited_overall_timestamp for the chat.
 * This is intentional to prevent old chats from jumping to the top of the list
 * when a draft is cleared (e.g. after message send or manual clear).
 */
export async function clearCurrentUserChatDraft(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
): Promise<Chat | null> {
  await dbInstance.init();
  try {
    const chat = await getChat(dbInstance, chat_id);
    if (chat) {
      console.debug(
        `[ChatDatabase] Clearing draft for chat ${chat_id}. Current draft_v: ${chat.draft_v}`,
      );

      // Preserve the consumed version locally so an in-flight sync snapshot
      // cannot restore the draft after this deletion.
      chat.cleared_draft_v = Math.max(
        chat.cleared_draft_v ?? 0,
        chat.draft_v ?? 0,
      );
      chat.encrypted_draft_md = null;
      chat.encrypted_draft_preview = null; // Clear preview as well
      chat.draft_v = 0; // Reset draft version to 0

      // CRITICAL: Don't update last_edited_overall_timestamp when clearing drafts.
      // Only messages should update this timestamp for proper sorting.
      // The chat should revert to its position based on last message timestamp.
      const nowTimestamp = Math.floor(Date.now() / 1000);
      chat.updated_at = nowTimestamp; // Keep updated_at for internal tracking

      // Use addChat without external transaction to ensure proper completion
      await addChat(dbInstance, chat);
      console.debug(
        `[ChatDatabase] Successfully cleared draft for chat ${chat_id}`,
      );
      return chat;
    }
    return null;
  } catch (error) {
    console.error(
      `[ChatDatabase] Error in clearCurrentUserChatDraft for chat ${chat_id}:`,
      error,
    );
    throw error;
  }
}

// ============================================================================
// BATCH/COMBINED OPERATIONS
// ============================================================================

/**
 * Add or update a chat with all its data (chat metadata + messages)
 */
export async function addOrUpdateChatWithFullData(
  dbInstance: ChatDatabaseInstance,
  chatData: Chat,
  messages: Message[] = [],
  transaction?: IDBTransaction,
  saveMessageFn?: (message: Message, tx?: IDBTransaction) => Promise<void>,
): Promise<void> {
  await dbInstance.init();
  console.debug(
    "[ChatDatabase] Adding/updating chat with full data:",
    chatData.chat_id,
  );
  const chatMetadata = { ...chatData };
  delete (chatMetadata as Partial<Chat> & { messages?: unknown }).messages; // Ensure messages are not part of chat metadata

  if (
    typeof chatMetadata.created_at === "string" ||
    (chatMetadata.created_at as unknown) instanceof Date
  ) {
    chatMetadata.created_at = Math.floor(
      new Date(chatMetadata.created_at as string | number | Date).getTime() /
        1000,
    );
  }
  if (
    typeof chatMetadata.updated_at === "string" ||
    (chatMetadata.updated_at as unknown) instanceof Date
  ) {
    chatMetadata.updated_at = Math.floor(
      new Date(chatMetadata.updated_at as string | number | Date).getTime() /
        1000,
    );
  }
  if (chatMetadata.encrypted_draft_md === undefined)
    chatMetadata.encrypted_draft_md = null;
  if (chatMetadata.encrypted_draft_preview === undefined)
    chatMetadata.encrypted_draft_preview = null;
  if (chatMetadata.draft_v === undefined) chatMetadata.draft_v = 0;

  const currentTransaction =
    transaction ||
    (await dbInstance.getTransaction(
      [dbInstance.CHATS_STORE_NAME, MESSAGES_STORE_NAME],
      "readwrite",
    ));

  const chatPromise = addChat(dbInstance, chatMetadata, currentTransaction);
  const messagePromises = saveMessageFn
    ? messages.map((msg) => saveMessageFn(msg, currentTransaction))
    : [];

  return new Promise<void>((resolve, reject) => {
    Promise.all([chatPromise, ...messagePromises])
      .then(() => {
        if (!transaction) {
          currentTransaction.oncomplete = () => resolve();
          currentTransaction.onerror = () => reject(currentTransaction.error);
        } else {
          resolve();
        }
      })
      .catch((error) => {
        if (!transaction && currentTransaction.abort)
          currentTransaction.abort();
        reject(error);
      });
  });
}

// ============================================================================
// METADATA-ONLY CHAT OPERATIONS (for expanded search coverage)
// ============================================================================

/**
 * Batch-save metadata-only chats to IndexedDB.
 *
 * These are chats from positions 101–1000 that have metadata (title, summary,
 * tags, icon, category) but no messages. They're stored in the same `chats`
 * object store as full chats, with `is_metadata_only: true` to distinguish them.
 *
 * Uses a single IndexedDB transaction for efficiency (~1-2ms per chat).
 * Skips chats that already exist in IndexedDB (avoids overwriting full chats
 * that may have been promoted from metadata-only).
 *
 * @param dbInstance - ChatDatabase instance
 * @param chats - Array of metadata-only Chat objects (with is_metadata_only: true)
 * @returns Number of chats actually saved (excludes already-existing ones)
 */
export async function batchSaveMetadataChats(
  dbInstance: ChatDatabaseInstance,
  chats: Chat[],
): Promise<number> {
  if (chats.length === 0) return 0;

  await dbInstance.init();

  // Pre-process all chats: encrypt and prepare for storage (async work done before transaction)
  const prepared: Chat[] = [];
  for (const chat of chats) {
    try {
      const isPublicChat =
        chat.chat_id?.startsWith("demo-") || chat.chat_id?.startsWith("legal-");
      const existingChat = chat.chat_id ? await dbInstance.getChat(chat.chat_id) : null;
      if (
        !chat.encrypted_chat_key &&
        !existingChat?.encrypted_chat_key &&
        !chat.is_anonymous &&
        !chat.anonymous_encrypted_chat_key &&
        !isPublicChat
      ) {
        console.warn(
          `[ChatDatabase] Skipping metadata-only synced chat ${chat.chat_id}: missing encrypted_chat_key`,
        );
        continue;
      }
      const chatToSave = await encryptChatForStorage(
        dbInstance,
        {
          ...chat,
          is_metadata_only: true,
          draft_v: chat.draft_v ?? 0,
          title_v: chat.title_v ?? 0,
          messages_v: chat.messages_v ?? 0,
          last_edited_overall_timestamp:
            chat.last_edited_overall_timestamp ??
            chat.updated_at ??
            chat.created_at ??
            Math.floor(Date.now() / 1000),
        },
        { isFromSync: true, forceIncomingEncryptedChatKey: false },
      );
      delete chatToSave.messages;
      prepared.push(chatToSave);
    } catch (error) {
      console.error(
        `[ChatDatabase] Error preparing metadata chat ${chat.chat_id} for storage:`,
        error,
      );
    }
  }

  if (prepared.length === 0) return 0;

  return new Promise<number>((resolve, reject) => {
    (async () => {
      try {
        const transaction = await dbInstance.getTransaction(
          dbInstance.CHATS_STORE_NAME,
          "readwrite",
        );
        const store = transaction.objectStore(dbInstance.CHATS_STORE_NAME);
        let savedCount = 0;

        for (const chat of prepared) {
          // Use put (upsert) — if the chat already exists as a full chat, keep it.
          // Check first: only save if not already present OR if already metadata-only.
          const getRequest = store.get(chat.chat_id);
          getRequest.onsuccess = () => {
            const existing = getRequest.result;
            if (existing && !existing.is_metadata_only) {
              // Already a full chat — don't overwrite with metadata-only
              return;
            }
            // Save metadata-only chat (new or updating existing metadata-only)
            store.put(chat);
            savedCount++;
          };
        }

        transaction.oncomplete = () => {
          console.debug(
            `[ChatDatabase] Batch saved ${savedCount}/${prepared.length} metadata-only chats`,
          );
          resolve(savedCount);
        };
        transaction.onerror = () => {
          console.error(
            "[ChatDatabase] Batch save metadata chats transaction failed:",
            transaction.error,
          );
          reject(transaction.error);
        };
      } catch (error) {
        reject(error);
      }
    })();
  });
}

/**
 * Get all metadata-only chat IDs currently in IndexedDB.
 * Used to send existing_chat_ids to the server during metadata sync
 * so unchanged chats can be skipped.
 *
 * @param dbInstance - ChatDatabase instance
 * @returns Array of chat IDs that are metadata-only
 */
export async function getMetadataOnlyChatIds(
  dbInstance: ChatDatabaseInstance,
): Promise<string[]> {
  await dbInstance.init();

  return new Promise<string[]>((resolve, reject) => {
    (async () => {
      try {
        const transaction = await dbInstance.getTransaction(
          dbInstance.CHATS_STORE_NAME,
          "readonly",
        );
        const store = transaction.objectStore(dbInstance.CHATS_STORE_NAME);
        const request = store.openCursor();
        const metadataOnlyIds: string[] = [];

        request.onsuccess = () => {
          const cursor = request.result;
          if (cursor) {
            if (cursor.value.is_metadata_only) {
              metadataOnlyIds.push(cursor.value.chat_id);
            }
            cursor.continue();
          }
        };

        transaction.oncomplete = () => {
          resolve(metadataOnlyIds);
        };
        transaction.onerror = () => {
          reject(transaction.error);
        };
      } catch (error) {
        reject(error);
      }
    })();
  });
}

// frontend/packages/ui/src/services/db/messageOperations.ts
// Handles message CRUD operations for the ChatDatabase class.
// These operations are extracted from db.ts for better code organization.
//
// This module contains:
// - Message saving (single and batch)
// - Message retrieval (by ID, by chat, all messages)
// - Message deletion
// - Duplicate detection and cleanup
// - Message status priority handling

import type { Message } from "../../types/chat";
import { writeWithQuotaRetry } from "./quotaRecovery";
import { chatKeyManager } from "../encryption/ChatKeyManager";
import { invalidateRecentChatWindow, invalidateRecentChatWindowForMessage } from "../recentChatWindowCache";

// Type for ChatDatabase instance to avoid circular import
// Only includes properties/methods needed by this module
interface ChatDatabaseInstance {
  db: IDBDatabase | null;
  init(): Promise<void>;
  getTransaction(
    storeNames: string | string[],
    mode: IDBTransactionMode,
  ): Promise<IDBTransaction>;

  // Message encryption/decryption methods (from chatKeyManagement)
  encryptMessageFields(message: Message, chatId: string): Promise<Message>;
  decryptMessageFields(message: Message, chatId: string): Promise<Message>;
}

// Store name constant (must match the one in db.ts)
const MESSAGES_STORE_NAME = "messages";
const MESSAGE_WINDOW_PAGES_STORE_NAME = "message_window_pages";
const DEFAULT_MESSAGE_WINDOW_LIMIT = 30;
const MAX_MESSAGE_WINDOW_LIMIT = 100;
const MESSAGE_WINDOW_PAGE_CACHE_GENERATION = 1;
const DEFAULT_MESSAGE_WINDOW_PAGE_CACHE_LIMIT = 12;
const DEFAULT_OFFLINE_CACHE_BUDGET_BYTES = 100 * 1024 * 1024;
const MAX_BUDGET_SCAN_PAGES = 4096;
const MAX_BUDGET_EVICTIONS = 32;
let configuredOfflineCacheBudgetBytes = DEFAULT_OFFLINE_CACHE_BUDGET_BYTES;
let lastBudgetCheckAt = 0;
let budgetTrim: Promise<number> | null = null;
let budgetTrimForced = false;

const UNSAFE_TO_EVICT_MESSAGE_STATUSES = new Set<Message["status"]>([
  "sending",
  "waiting_for_upload",
  "waiting_for_internet",
  "queued",
  "processing",
  "streaming",
  "failed",
  "waiting_for_user",
  "delivered",
]);

export type MessageWindowDirection = "latest" | "before" | "after" | "around";

export interface MessageWindowOptions {
  direction?: MessageWindowDirection;
  limit?: number;
  anchorMessageId?: string;
  anchorCreatedAt?: number;
  beforeTimestamp?: number;
  beforeMessageId?: string;
  afterTimestamp?: number;
  afterMessageId?: string;
  compressedUpToTimestamp?: number;
}

export interface MessageWindowResult {
  messages: Message[];
  hasMoreBefore: boolean;
  hasMoreAfter: boolean;
  startCursor: number | null;
  startCursorMessageId: string | null;
  endCursor: number | null;
  endCursorMessageId: string | null;
  anchorFound: boolean;
}

export type MessageWindowPageKind = "normal" | "forgotten";

export interface MessageWindowPageCacheRecord {
  id: string;
  chat_id: string;
  page_kind: MessageWindowPageKind;
  direction: MessageWindowDirection;
  start_cursor: number | null;
  start_cursor_message_id: string | null;
  end_cursor: number | null;
  end_cursor_message_id: string | null;
  has_more_before: boolean;
  has_more_after: boolean;
  message_ids: string[];
  cached_at: number;
  last_accessed_at: number;
  cache_generation: number;
}

export interface RecordMessageWindowPageOptions {
  direction?: MessageWindowDirection;
  pageKind?: MessageWindowPageKind;
  now?: number;
}

export interface EvictMessageWindowPagesOptions {
  maxPagesPerChat?: number;
  protectedPageIds?: string[];
  protectedMessageIds?: string[];
}

export interface EvictMessageWindowPagesResult {
  deletedPageIds: string[];
  deletedMessageIds: string[];
}

function requestToPromise<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function clampWindowLimit(limit?: number): number {
  if (!Number.isFinite(limit) || !limit || limit < 1) {
    return DEFAULT_MESSAGE_WINDOW_LIMIT;
  }
  return Math.min(Math.floor(limit), MAX_MESSAGE_WINDOW_LIMIT);
}

function chatRange(
  chatId: string,
  lowerTimestamp: number = -Infinity,
  upperTimestamp: number = Infinity,
  lowerOpen = false,
  upperOpen = false,
): IDBKeyRange {
  return IDBKeyRange.bound(
    [chatId, lowerTimestamp],
    [chatId, upperTimestamp],
    lowerOpen,
    upperOpen,
  );
}

function readCursorWindow(
  index: IDBIndex,
  range: IDBKeyRange,
  direction: IDBCursorDirection,
  limit: number,
  includeRecord: (record: Message) => boolean = () => true,
): Promise<{ records: Message[]; hasMore: boolean }> {
  return new Promise((resolve, reject) => {
    const records: Message[] = [];
    const request = index.openCursor(range, direction);

    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        resolve({ records, hasMore: false });
        return;
      }
      if (records.length >= limit) {
        resolve({ records, hasMore: true });
        return;
      }
      const record = cursor.value as Message;
      if (includeRecord(record)) {
        records.push(record);
      }
      cursor.continue();
    };
    request.onerror = () => reject(request.error);
  });
}

async function decryptWindow(
  dbInstance: ChatDatabaseInstance,
  records: Message[],
  chatId: string,
): Promise<Message[]> {
  return Promise.all(records.map((msg) => dbInstance.decryptMessageFields(msg, chatId)));
}

function windowResult(
  messages: Message[],
  hasMoreBefore: boolean,
  hasMoreAfter: boolean,
  anchorFound = true,
): MessageWindowResult {
  return {
    messages,
    hasMoreBefore,
    hasMoreAfter,
    startCursor: messages[0]?.created_at ?? null,
    startCursorMessageId: messages[0]?.message_id ?? null,
    endCursor: messages[messages.length - 1]?.created_at ?? null,
    endCursorMessageId: messages[messages.length - 1]?.message_id ?? null,
    anchorFound,
  };
}

function compareMessageCursorPosition(message: Message, timestamp: number, messageId?: string): number {
  if (message.created_at !== timestamp) {
    return message.created_at < timestamp ? -1 : 1;
  }
  if (!messageId) return 0;
  return message.message_id.localeCompare(messageId);
}

function buildMessageWindowPageId(
  chatId: string,
  pageKind: MessageWindowPageKind,
  direction: MessageWindowDirection,
  result: MessageWindowResult,
): string {
  return [
    chatId,
    pageKind,
    direction,
    result.startCursor ?? "start",
    result.startCursorMessageId ?? "start-id",
    result.endCursor ?? "end",
    result.endCursorMessageId ?? "end-id",
    MESSAGE_WINDOW_PAGE_CACHE_GENERATION,
  ].join("|");
}

export function isSafeToEvictMessage(message: Message | undefined): boolean {
  if (!message) return false;
  const raw = message as Message & Record<string, unknown>;
  return message.status === "synced" &&
    !UNSAFE_TO_EVICT_MESSAGE_STATUSES.has(message.status) &&
    !raw.pending_turn_preflight_v1 &&
    !raw.pending_encrypted_turn_preflight_v1 &&
    !raw.pending_encrypted_embed_bundle_v1;
}

/** Configure the whole-origin cache target; protected data may exceed it. */
export function configureOfflineCacheBudget(bytes: number): void {
  if (!Number.isSafeInteger(bytes) || bytes < 1) throw new Error("Invalid offline cache budget");
  configuredOfflineCacheBudgetBytes = bytes;
  lastBudgetCheckAt = 0;
}

export function offlineCacheTargetBytes(quota?: number): number {
  return quota && Number.isFinite(quota) && quota > 0
    ? Math.min(configuredOfflineCacheBudgetBytes, Math.floor(quota / 2))
    : configuredOfflineCacheBudgetBytes;
}

async function deleteConfirmedMessage(
  dbInstance: ChatDatabaseInstance,
  messageId: string,
): Promise<boolean> {
  const transaction = await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readwrite");
  return new Promise((resolve, reject) => {
    const store = transaction.objectStore(MESSAGES_STORE_NAME);
    let deleted = false;
    const request = store.get(messageId);
    request.onsuccess = () => {
      if (!isSafeToEvictMessage(request.result as Message | undefined)) return;
      store.delete(messageId);
      deleted = true;
    };
    request.onerror = () => reject(request.error);
    transaction.oncomplete = () => resolve(deleted);
    transaction.onerror = () => reject(transaction.error);
    transaction.onabort = () => reject(transaction.error ?? new Error("Cache eviction aborted"));
  });
}

function pageRecordsForChatRange(chatId: string): IDBKeyRange {
  return IDBKeyRange.bound([chatId, -Infinity], [chatId, Infinity]);
}

// ============================================================================
// MESSAGE STATUS PRIORITY
// ============================================================================

/**
 * Status priority map for determining which message version to keep
 * Higher priority means the message has progressed further in its lifecycle
 */
const STATUS_PRIORITY: Record<string, number> = {
  sending: 1,
  waiting_for_upload: 1, // Upload in progress, same level as sending
  waiting_for_internet: 1,
  queued: 3.1, // Server queue admission survives an ordinary synced/delivered refresh
  processing: 2,
  streaming: 2,
  waiting_for_user: 2.3, // Higher than streaming/processing, lower than failed - chat paused for user action
  failed: 2.5,
  delivered: 2.8, // Server received the message, awaiting full sync confirmation
  synced: 3,
};

/**
 * Determines if a new message should update an existing message.
 *
 * Rules:
 * - Always allow streaming -> streaming updates (content grows over time).
 * - Never allow synced to overwrite waiting_for_user. 'waiting_for_user' is a
 *   terminal client-side display state (e.g. credits-rejection, permissions request).
 *   Phased sync delivers these messages from Directus with status='synced' (the
 *   server-side storage status), but the client must keep 'waiting_for_user' so
 *   the Buy Credits button, header banner, and typing indicator suppression remain
 *   correct after a tab reload.
 * - Otherwise, allow updates when status priority increases.
 */
export function shouldUpdateMessage(
  existing: Message,
  incoming: Message,
): boolean {
  if (existing.queue_dispatch_status === "paused" &&
      (incoming.queue_dispatch_status === "queued" || incoming.queue_dispatch_status === "processing")) {
    return false; // This increment has no same-ID resume; older receipts cannot revive a paused turn.
  }
  if (existing.queue_dispatch_status === "processing" && incoming.queue_dispatch_status === "queued") {
    return false; // An older queued receipt cannot undo a durable task handoff.
  }
  if ((existing.status === "queued" || existing.queue_dispatch_status === "processing") &&
      incoming.queue_dispatch_status === "paused") {
    return true; // Failure receipt supersedes both pending and consumed Steer states.
  }
  if (existing.status === "queued" && Number.isSafeInteger(incoming.queue_revision) &&
      (incoming.queue_revision ?? 0) >= (existing.queue_revision ?? 0) &&
      incoming.queue_dispatch_status === "processing") {
    return true; // Durable server handoff receipt clears queued UI after missed WS events.
  }
  if (existing.status === "queued" && Number.isSafeInteger(incoming.queue_revision) &&
      (incoming.queue_revision ?? 0) > (existing.queue_revision ?? 0)) {
    return true; // A newer encrypted edit revision must replace a stale local body.
  }
  // Streaming chunks must be able to update the same message id.
  if (existing.status === "streaming" && incoming.status === "streaming") {
    return true;
  }

  // Never overwrite a waiting_for_user message with synced or delivered from phased sync.
  // 'waiting_for_user' is a terminal client-side display state that the server doesn't
  // persist — Directus has no status column, so phased sync messages arrive with no status
  // and prepareMessagesForStorage() assigns 'delivered' as the default. Since 'delivered'
  // has higher priority (2.8) than 'waiting_for_user' (2.3), the priority check below would
  // allow the overwrite. This would clobber the client state and hide the Buy Credits button
  // and the credits-error header after a page reload.
  // Guard both 'synced' (from chat_message_confirmed events) and 'delivered' (from phased sync).
  if (
    existing.status === "waiting_for_user" &&
    (incoming.status === "synced" || incoming.status === "delivered")
  ) {
    return false;
  }

  const existingPriority = STATUS_PRIORITY[existing.status] ?? 0;
  const incomingPriority = STATUS_PRIORITY[incoming.status] ?? 0;

  if (incomingPriority > existingPriority) {
    return true;
  }

  if (incomingPriority === existingPriority && existing.status === incoming.status) {
    if (existing.content !== incoming.content) return false;

    if (
      existing.model_name !== incoming.model_name ||
      existing.category !== incoming.category ||
      existing.thinking_content !== incoming.thinking_content ||
      existing.thinking_signature !== incoming.thinking_signature ||
      existing.thinking_token_count !== incoming.thinking_token_count ||
      existing.has_thinking !== incoming.has_thinking
    ) {
      return true;
    }
  }

  return false;
}

/**
 * Returns true if the incoming encrypted record adds encrypted fields that are missing on the existing record.
 * This is important for placeholder messages (e.g. assistant message created before first chunk arrives).
 */
export function hasNewEncryptedFields(
  existing: Message,
  incomingEncrypted: Message,
): boolean {
  const pairs: Array<[keyof Message, keyof Message]> = [
    ["encrypted_content", "encrypted_content"],
    ["encrypted_sender_name", "encrypted_sender_name"],
    ["encrypted_category", "encrypted_category"],
    ["encrypted_model_name", "encrypted_model_name"],
    // Thinking content/signature must be persisted even if status doesn't advance.
    ["encrypted_thinking_content", "encrypted_thinking_content"],
    ["encrypted_thinking_signature", "encrypted_thinking_signature"],
    // PII mappings for client-side restoration of anonymized data
    ["encrypted_pii_mappings", "encrypted_pii_mappings"],
  ];

  return pairs.some(([existingKey, incomingKey]) => {
    const existingValue = existing[existingKey];
    const incomingValue = incomingEncrypted[incomingKey];
    return !existingValue && !!incomingValue;
  });
}

function hasNewerStoredRevision(stored: Message, incoming: Message): boolean {
  return Number.isSafeInteger(stored.queue_revision) &&
    Number.isSafeInteger(incoming.queue_revision) &&
    (stored.queue_revision ?? 0) > (incoming.queue_revision ?? 0);
}

// ============================================================================
// DUPLICATE DETECTION
// ============================================================================

/**
 * Determines if two messages are content duplicates (same logical message, different IDs)
 *
 * CRITICAL: For assistant messages, we also check if the message_id matches the task_id pattern
 * to avoid false positives when the same response is saved with different IDs from different sources.
 */
export function isContentDuplicate(
  existing: Message,
  incoming: Message,
): boolean {
  // Must be same chat, role, and have similar content
  if (
    existing.chat_id !== incoming.chat_id ||
    existing.role !== incoming.role
  ) {
    return false;
  }

  // Repeating text is a new user submission when its stable message ID differs.
  // Retries and sync copies retain that ID and use the primary-key save path.
  if (existing.role === "user" && existing.message_id !== incoming.message_id) {
    return false;
  }

  // For assistant messages, if message_ids are different but both look like task IDs (UUIDs),
  // and content matches, they might be the same message from different sync sources.
  // However, we should be more careful - only treat as duplicate if encrypted_content matches
  // AND timestamps are very close (within 1 minute for assistant messages to account for streaming delays)
  const isAssistantMessage =
    existing.role === "assistant" && incoming.role === "assistant";
  const timeThreshold = isAssistantMessage ? 60 : 300; // 1 minute for assistant, 5 minutes for user

  // Prefer encrypted content when both records have it. When this function is
  // called after getMessagesForChat(), records may already be decrypted and
  // encrypted_content is intentionally absent; two missing encrypted fields are
  // not evidence of duplicate content.
  const hasEncryptedContent = !!existing.encrypted_content && !!incoming.encrypted_content;
  const contentMatch = hasEncryptedContent
    ? existing.encrypted_content === incoming.encrypted_content
    : !!existing.content && !!incoming.content && existing.content === incoming.content;

  // Check if timestamps are close (within threshold) - messages from different sync sources
  const timeDiff = Math.abs(existing.created_at - incoming.created_at);
  const timeMatch = timeDiff < timeThreshold;

  // Check if sender names match (for user messages)
  // For assistant messages, sender_name is typically null/undefined, so this check is less relevant
  const senderMatch =
    existing.encrypted_sender_name === incoming.encrypted_sender_name ||
    (existing.role === "assistant" && incoming.role === "assistant");

  const isDuplicate = contentMatch && timeMatch && senderMatch;

  if (isDuplicate && isAssistantMessage) {
    console.debug(
      `[ChatDatabase] Detected potential duplicate assistant message: ` +
        `existing=${existing.message_id}, incoming=${incoming.message_id}, ` +
        `timeDiff=${timeDiff}s, contentMatch=${contentMatch}`,
    );
  }

  return isDuplicate;
}

/**
 * Finds content-based duplicates (same content but different message_id)
 * This handles cases where the same logical message has different IDs from different sync sources
 */
export async function findContentDuplicate(
  dbInstance: ChatDatabaseInstance,
  message: Message,
  transaction?: IDBTransaction,
): Promise<Message | null> {
  try {
    // Get all messages for the same chat
    const chatMessages = await getMessagesForChat(
      dbInstance,
      message.chat_id,
      transaction,
    );

    // Look for messages with same content, role, and similar timestamp
    for (const existingMessage of chatMessages) {
      if (existingMessage.message_id === message.message_id) {
        continue; // Skip same message_id
      }

      // Check if it's the same logical message based on content and timing
      if (isContentDuplicate(existingMessage, message)) {
        return existingMessage;
      }
    }

    return null;
  } catch (error) {
    console.error("[ChatDatabase] Error finding content duplicate:", error);
    return null;
  }
}

