/**
 * Get a single message by ID
 */
export async function getMessage(
  dbInstance: ChatDatabaseInstance,
  message_id: string,
  transaction?: IDBTransaction,
): Promise<Message | null> {
  await dbInstance.init();
  const currentTransaction =
    transaction ||
    (await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readonly"));
  return new Promise((resolve, reject) => {
    const store = currentTransaction.objectStore(MESSAGES_STORE_NAME);
    const request = store.get(message_id);

    request.onsuccess = () => {
      const encryptedMessage = request.result;
      if (!encryptedMessage) {
        resolve(null);
        return;
      }
      // Decrypt message before returning (zero-knowledge architecture)
      // CRITICAL FIX: await decryption operation since decryptMessageFields is now async
      (async () => {
        try {
          const decryptedMessage = await dbInstance.decryptMessageFields(
            encryptedMessage,
            encryptedMessage.chat_id,
          );
          resolve(decryptedMessage);
        } catch (error) {
          console.error(
            `[ChatDatabase] Error decrypting message ${message_id}:`,
            error,
          );
          reject(error);
        }
      })();
    };
    request.onerror = () => {
      console.error(
        `[ChatDatabase] Error getting message ${message_id}:`,
        request.error,
      );
      reject(request.error);
    };
  });
}

/**
 * Get the count of messages for a specific chat without decrypting them.
 * Uses IDB index.count() which is O(1) — no record access or decryption needed.
 * Use this instead of getMessagesForChat() when only the count is needed.
 */
export async function getMessageCountForChat(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
  transaction?: IDBTransaction,
): Promise<number> {
  await dbInstance.init();
  const currentTransaction =
    transaction ||
    (await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readonly"));
  return new Promise((resolve, reject) => {
    const store = currentTransaction.objectStore(MESSAGES_STORE_NAME);
    const index = store.index("chat_id");
    const request = index.count(IDBKeyRange.only(chat_id));
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => {
      console.error(
        `[ChatDatabase] Error counting messages for chat ${chat_id}:`,
        request.error,
      );
      reject(request.error);
    };
  });
}

/**
 * Get all messages for a specific chat
 */
export async function getMessagesForChat(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
  transaction?: IDBTransaction,
): Promise<Message[]> {
  await dbInstance.init();
  const currentTransaction =
    transaction ||
    (await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readonly"));
  return new Promise((resolve, reject) => {
    const store = currentTransaction.objectStore(MESSAGES_STORE_NAME);
    const index = store.index("chat_id_created_at"); // Use compound index for fetching and sorting
    const request = index.getAll(
      IDBKeyRange.bound([chat_id, -Infinity], [chat_id, Infinity]),
    ); // Get all for chat_id, sorted by created_at

    request.onsuccess = async () => {
      const encryptedMessages = request.result || [];
      // Decrypt all messages before returning (zero-knowledge architecture)
      // CRITICAL FIX: await all decryption operations since decryptMessageFields is now async
      const decryptedMessages = await Promise.all(
        encryptedMessages.map((msg) =>
          dbInstance.decryptMessageFields(msg, chat_id),
        ),
      );
      resolve(decryptedMessages);
    };
    request.onerror = () => {
      console.error(
        `[ChatDatabase] Error getting messages for chat ${chat_id}:`,
        request.error,
      );
      reject(request.error);
    };
  });
}

/**
 * Get a bounded message window for scalable chat opening and virtualized history.
 * This intentionally uses cursors instead of getAll(), so it reads and decrypts
 * only the requested window plus one sentinel row for has-more detection.
 */
export async function getMessageWindowForChat(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
  options: MessageWindowOptions = {},
  transaction?: IDBTransaction,
): Promise<MessageWindowResult> {
  await dbInstance.init();
  const limit = clampWindowLimit(options.limit);
  const direction = options.direction ?? "latest";

  let anchorRecord: Message | null = null;
  if (direction === "around" && options.anchorMessageId) {
    const anchorTransaction = await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readonly");
    anchorRecord = await new Promise<Message | null>((resolve, reject) => {
      const request = anchorTransaction.objectStore(MESSAGES_STORE_NAME).get(options.anchorMessageId!);
      request.onsuccess = () => resolve((request.result as Message | undefined) ?? null);
      request.onerror = () => reject(request.error);
    });
    if (anchorRecord?.chat_id !== chat_id) {
      anchorRecord = null;
    }
  }

  const currentTransaction =
    transaction ||
    (await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readonly"));
  const store = currentTransaction.objectStore(MESSAGES_STORE_NAME);
  const index = store.index("chat_id_created_at");

  if (direction === "around") {
    const anchorCreatedAt = anchorRecord?.created_at ?? options.anchorCreatedAt;
    if (!anchorCreatedAt) {
      return windowResult([], false, false, false);
    }

    const beforeLimit = Math.floor((limit - 1) / 2);
    const afterLimit = limit - 1 - beforeLimit;
    const before = beforeLimit > 0
      ? await readCursorWindow(
          index,
          chatRange(chat_id, options.compressedUpToTimestamp ?? -Infinity, anchorCreatedAt, !!options.compressedUpToTimestamp, false),
          "prev",
          beforeLimit,
          (message) => compareMessageCursorPosition(message, anchorCreatedAt, options.anchorMessageId) < 0,
        )
      : { records: [], hasMore: false };
    const after = afterLimit > 0
      ? await readCursorWindow(
          index,
          chatRange(chat_id, anchorCreatedAt, Infinity, true, false),
          "next",
          afterLimit,
          (message) => compareMessageCursorPosition(message, anchorCreatedAt, options.anchorMessageId) > 0,
        )
      : { records: [], hasMore: false };
    const encryptedMessages = [
      ...before.records.reverse(),
      ...(anchorRecord ? [anchorRecord] : []),
      ...after.records,
    ];
    const messages = await decryptWindow(dbInstance, encryptedMessages, chat_id);
    return windowResult(messages, before.hasMore, after.hasMore, !!anchorRecord || !!options.anchorCreatedAt);
  }

  if (direction === "before") {
    const beforeTimestamp = options.beforeTimestamp ?? options.anchorCreatedAt;
    if (!beforeTimestamp) return windowResult([], false, false, false);
    const { records, hasMore } = await readCursorWindow(
      index,
      chatRange(chat_id, options.compressedUpToTimestamp ?? -Infinity, beforeTimestamp, !!options.compressedUpToTimestamp, false),
      "prev",
      limit,
      (message) => compareMessageCursorPosition(message, beforeTimestamp, options.beforeMessageId) < 0,
    );
    const messages = await decryptWindow(dbInstance, records.reverse(), chat_id);
    return windowResult(messages, hasMore, true);
  }

  if (direction === "after") {
    const afterTimestamp = options.afterTimestamp ?? options.anchorCreatedAt;
    if (!afterTimestamp) return windowResult([], false, false, false);
    const { records, hasMore } = await readCursorWindow(
      index,
      chatRange(chat_id, afterTimestamp, Infinity, false, false),
      "next",
      limit,
      (message) => compareMessageCursorPosition(message, afterTimestamp, options.afterMessageId) > 0,
    );
    const messages = await decryptWindow(dbInstance, records, chat_id);
    return windowResult(messages, true, hasMore);
  }

  const { records, hasMore } = await readCursorWindow(
    index,
    chatRange(chat_id, options.compressedUpToTimestamp ?? -Infinity, Infinity, !!options.compressedUpToTimestamp, false),
    "prev",
    limit,
  );
  const messages = await decryptWindow(dbInstance, records.reverse(), chat_id);
  return windowResult(messages, hasMore, false);
}

/**
 * Record metadata for an encrypted message window cached in IndexedDB.
 * The metadata is intentionally separate from messages_v: it describes viewed
 * pages only and must never be treated as full local sync completeness.
 */
export async function recordMessageWindowPage(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
  result: MessageWindowResult,
  options: RecordMessageWindowPageOptions = {},
): Promise<MessageWindowPageCacheRecord | null> {
  if (result.messages.length === 0) return null;
  await dbInstance.init();

  const direction = options.direction ?? "latest";
  const pageKind = options.pageKind ?? "normal";
  const now = options.now ?? Date.now();
  const id = buildMessageWindowPageId(chat_id, pageKind, direction, result);
  const readTransaction = await dbInstance.getTransaction(
    MESSAGE_WINDOW_PAGES_STORE_NAME,
    "readonly",
  );
  const existing = await requestToPromise<MessageWindowPageCacheRecord | undefined>(
    readTransaction.objectStore(MESSAGE_WINDOW_PAGES_STORE_NAME).get(id),
  );
  const record: MessageWindowPageCacheRecord = {
    id,
    chat_id,
    page_kind: pageKind,
    direction,
    start_cursor: result.startCursor,
    start_cursor_message_id: result.startCursorMessageId,
    end_cursor: result.endCursor,
    end_cursor_message_id: result.endCursorMessageId,
    has_more_before: result.hasMoreBefore,
    has_more_after: result.hasMoreAfter,
    message_ids: result.messages.map((message) => message.message_id),
    cached_at: existing?.cached_at ?? now,
    last_accessed_at: now,
    cache_generation: MESSAGE_WINDOW_PAGE_CACHE_GENERATION,
  };
  const writeTransaction = await dbInstance.getTransaction(
    MESSAGE_WINDOW_PAGES_STORE_NAME,
    "readwrite",
  );
  await requestToPromise(writeTransaction.objectStore(MESSAGE_WINDOW_PAGES_STORE_NAME).put(record));
  void enforceOfflineCacheBudget(dbInstance).catch((error) => {
    console.warn("[ChatDatabase] Offline cache budget check failed:", error);
  });
  return record;
}

export async function getMessageWindowPagesForChat(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
): Promise<MessageWindowPageCacheRecord[]> {
  await dbInstance.init();
  const transaction = await dbInstance.getTransaction(
    MESSAGE_WINDOW_PAGES_STORE_NAME,
    "readonly",
  );
  const store = transaction.objectStore(MESSAGE_WINDOW_PAGES_STORE_NAME);
  const index = store.index("chat_id_last_accessed_at");
  const records = await requestToPromise<MessageWindowPageCacheRecord[]>(
    index.getAll(pageRecordsForChatRange(chat_id)),
  );
  return (records || []).filter(
    (record) => record.cache_generation === MESSAGE_WINDOW_PAGE_CACHE_GENERATION,
  );
}

/**
 * Evict old cached normal window pages using conservative safety exclusions.
 * Forgotten pages are never evicted here; they are only loaded after an explicit
 * reveal and stay available until normal chat teardown/cleanup paths run.
 */
export async function evictStaleMessageWindowPages(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
  options: EvictMessageWindowPagesOptions = {},
): Promise<EvictMessageWindowPagesResult> {
  const maxPagesPerChat = Math.max(1, Math.floor(options.maxPagesPerChat ?? DEFAULT_MESSAGE_WINDOW_PAGE_CACHE_LIMIT));
  const protectedPageIds = new Set(options.protectedPageIds ?? []);
  const protectedMessageIds = new Set(options.protectedMessageIds ?? []);
  const pages = await getMessageWindowPagesForChat(dbInstance, chat_id);
  const normalPages = pages
    .filter((page) => page.page_kind === "normal" && !protectedPageIds.has(page.id))
    .sort((a, b) => a.last_accessed_at - b.last_accessed_at);
  const deleteCount = Math.max(0, pages.filter((page) => page.page_kind === "normal").length - maxPagesPerChat);
  const pagesToDelete: MessageWindowPageCacheRecord[] = [];
  for (const page of normalPages) {
    if (pagesToDelete.length >= deleteCount) break;
    if (page.message_ids.some((id) => protectedMessageIds.has(id))) continue;
    let confirmed = true;
    for (const messageId of page.message_ids) {
      const readTransaction = await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readonly");
      const message = await requestToPromise<Message | undefined>(
        readTransaction.objectStore(MESSAGES_STORE_NAME).get(messageId),
      );
      if (!isSafeToEvictMessage(message)) {
        confirmed = false;
        break;
      }
    }
    if (confirmed) pagesToDelete.push(page);
  }
  if (pagesToDelete.length === 0) {
    return { deletedPageIds: [], deletedMessageIds: [] };
  }
  invalidateRecentChatWindow(chat_id, 'message');

  const deletingPageIds = new Set(pagesToDelete.map((page) => page.id));
  const retainedMessageIds = new Set<string>();
  for (const page of pages) {
    if (deletingPageIds.has(page.id)) continue;
    for (const messageId of page.message_ids) retainedMessageIds.add(messageId);
  }

  const deletedPageIds: string[] = [];
  const deletedMessageIds: string[] = [];
  for (const page of pagesToDelete) {
    const pageTransaction = await dbInstance.getTransaction(
      MESSAGE_WINDOW_PAGES_STORE_NAME,
      "readwrite",
    );
    await requestToPromise(pageTransaction.objectStore(MESSAGE_WINDOW_PAGES_STORE_NAME).delete(page.id));
    deletedPageIds.push(page.id);

    for (const messageId of page.message_ids) {
      if (retainedMessageIds.has(messageId) || protectedMessageIds.has(messageId)) continue;
      if (await deleteConfirmedMessage(dbInstance, messageId)) deletedMessageIds.push(messageId);
    }
  }

  if (deletedMessageIds.length > 0) invalidateRecentChatWindow(chat_id, 'message');
  return { deletedPageIds, deletedMessageIds };
}

/**
 * Trim only confirmed, reproducible message pages when whole-origin usage is
 * over its target. The scan and deletion count are bounded so a large account
 * cannot stall an ordinary chat save. `force` is used once after quota failure.
 */
export async function enforceOfflineCacheBudget(
  dbInstance: ChatDatabaseInstance,
  force = false,
): Promise<number> {
  if (!force && Date.now() - lastBudgetCheckAt < 30_000) return 0;
  if (budgetTrim) {
    if (!force || budgetTrimForced) return budgetTrim;
    await budgetTrim.catch(() => 0);
    return enforceOfflineCacheBudget(dbInstance, true);
  }
  lastBudgetCheckAt = Date.now();
  budgetTrimForced = force;
  budgetTrim = (async () => {
    const storage = typeof navigator !== "undefined" ? navigator.storage : undefined;
    const estimate = await storage?.estimate?.().catch(() => undefined);
    const target = offlineCacheTargetBytes(estimate?.quota);
    if (!force && (estimate?.usage === undefined || estimate.usage <= target)) return 0;

    await dbInstance.init();
    const transaction = await dbInstance.getTransaction(MESSAGE_WINDOW_PAGES_STORE_NAME, "readonly");
    const pages = await requestToPromise<MessageWindowPageCacheRecord[]>(
      transaction.objectStore(MESSAGE_WINDOW_PAGES_STORE_NAME).getAll(undefined, MAX_BUDGET_SCAN_PAGES),
    );
    const normalPages = pages
      .filter((page) => page.page_kind === "normal" &&
        page.cache_generation === MESSAGE_WINDOW_PAGE_CACHE_GENERATION)
      .sort((a, b) => a.last_accessed_at - b.last_accessed_at);
    let removed = 0;
    for (const page of normalPages) {
      if (removed >= MAX_BUDGET_EVICTIONS) break;
      const count = (await getMessageWindowPagesForChat(dbInstance, page.chat_id))
        .filter((candidate) => candidate.page_kind === "normal").length;
      if (count <= 1) continue;
      const result = await evictStaleMessageWindowPages(dbInstance, page.chat_id, {
        maxPagesPerChat: count - 1,
      });
      if (result.deletedPageIds.length === 0) continue;
      removed += result.deletedPageIds.length;
      if (!force && removed % 4 === 0) {
        const current = await storage?.estimate?.().catch(() => undefined);
        if (current?.usage !== undefined && current.usage <= target) break;
      }
    }
    return removed;
  })().finally(() => { budgetTrim = null; budgetTrimForced = false; });
  return budgetTrim;
}

/**
 * Get only the last message for a chat (efficient for sidebar display)
 * This avoids decrypting all messages when we only need the last one
 */
export async function getLastMessageForChat(
  dbInstance: ChatDatabaseInstance,
  chat_id: string,
  transaction?: IDBTransaction,
): Promise<Message | null> {
  await dbInstance.init();
  const currentTransaction =
    transaction ||
    (await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readonly"));
  return new Promise((resolve, reject) => {
    const store = currentTransaction.objectStore(MESSAGES_STORE_NAME);
    const index = store.index("chat_id_created_at");
    // Use openCursor with 'prev' direction to get the last message (highest created_at)
    const request = index.openCursor(
      IDBKeyRange.bound([chat_id, -Infinity], [chat_id, Infinity]),
      "prev",
    );

    request.onsuccess = async () => {
      const cursor = request.result;
      if (cursor) {
        // Found the last message - decrypt and return it
        const encryptedMessage = cursor.value;
        try {
          const decryptedMessage = await dbInstance.decryptMessageFields(
            encryptedMessage,
            chat_id,
          );
          resolve(decryptedMessage);
        } catch (error) {
          console.error(
            `[ChatDatabase] Error decrypting last message for chat ${chat_id}:`,
            error,
          );
          resolve(null);
        }
      } else {
        // No messages found
        resolve(null);
      }
    };
    request.onerror = () => {
      console.error(
        `[ChatDatabase] Error getting last message for chat ${chat_id}:`,
        request.error,
      );
      reject(request.error);
    };
  });
}

/**
 * Get all messages from the database
 * Used for retrying pending messages when connection is restored
 * Can be called during init() (via cleanupDuplicateMessages) or after init()
 * @param dbInstance The ChatDatabase instance
 * @param duringInit If true, uses direct transaction instead of getTransaction (to avoid init deadlock)
 * @returns Promise resolving to array of all messages
 */
export async function getAllMessages(
  dbInstance: ChatDatabaseInstance,
  duringInit: boolean = false,
): Promise<Message[]> {
  // Only call init() if not already during init (to avoid deadlock)
  if (!duringInit) {
    await dbInstance.init();
  }

  if (!dbInstance.db) {
    throw new Error("Database not initialized");
  }

  // Use appropriate transaction method based on context
  const transaction = duringInit
    ? dbInstance.db.transaction(MESSAGES_STORE_NAME, "readonly")
    : await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readonly");

  return new Promise((resolve, reject) => {
    const store = transaction.objectStore(MESSAGES_STORE_NAME);
    const request = store.getAll();

    request.onsuccess = async () => {
      const encryptedMessages = request.result || [];
      // Decrypt all messages before returning (zero-knowledge architecture)
      // CRITICAL FIX: await all decryption operations since decryptMessageFields is now async
      const decryptedMessages = await Promise.all(
        encryptedMessages.map((msg) =>
          dbInstance.decryptMessageFields(msg, msg.chat_id),
        ),
      );
      resolve(decryptedMessages);
    };
    request.onerror = () => {
      console.error(
        "[ChatDatabase] Error getting all messages:",
        request.error,
      );
      reject(request.error);
    };
  });
}

export type PendingMessageRetryKind = "pending_turn" | "waiting_for_internet" | "sending";
export type PendingMessageRetryCursor = [number | string, number, string];
const MAX_PENDING_RETRY_PAGE_BYTES = 4 * 1024 * 1024;
// A single legitimate sealed turn can exceed a page. Process it alone, up to
// the recovery payload ceiling; larger rows remain durable and are reported.
const MAX_PENDING_RETRY_SINGLE_ROW_BYTES = 24 * 1024 * 1024;

export async function decryptPendingMessageRetryRow(
  dbInstance: ChatDatabaseInstance, raw: Message,
): Promise<Message | null> {
  try {
    const message = await dbInstance.decryptMessageFields(raw, raw.chat_id);
    if (typeof message.content !== "string" || !message.content ||
        message.content === "[Decrypting...]" ||
        message.content === "[Content decryption failed]" ||
        (message as Message & { _decryptionPending?: boolean })._decryptionPending) return null;
    return message;
  } catch (error) {
    console.warn("[ChatDatabase] Pending message key is not ready:", error);
    return null;
  }
}

/**
 * Read one bounded page of pending raw user rows from a secondary index.
 * The caller decrypts each row independently after the IDB transaction closes.
 * A pending sealed turn is included even if an unrelated metadata event changed
 * its display status before the exact committed-version acknowledgement.
 */
export async function getPendingMessageRetryPage(
  dbInstance: ChatDatabaseInstance,
  kind: PendingMessageRetryKind,
  after: PendingMessageRetryCursor | null = null,
  limit = 20,
): Promise<{ rows: Message[]; nextCursor: PendingMessageRetryCursor | null; oversizedCount: number }> {
  if (!Number.isSafeInteger(limit) || limit < 1 || limit > 20) {
    throw new Error("Pending message retry page limit is invalid.");
  }
  const indexName = kind === "pending_turn"
    ? "pending_turn_created_at_message_id"
    : "status_created_at_message_id";
  const key: number | string = kind === "pending_turn" ? 1 : kind;
  if (after && (after[0] !== key || !Number.isSafeInteger(after[1]) ||
      typeof after[2] !== "string")) {
    throw new Error("Pending message retry cursor changed scope.");
  }
  const transaction = await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readonly");
  const index = transaction.objectStore(MESSAGES_STORE_NAME).index(indexName);
  const range = IDBKeyRange.bound(
    after ?? [key, 0, ""], [key, Number.MAX_SAFE_INTEGER, "\uffff"],
    after !== null, false,
  );
  return new Promise((resolve, reject) => {
    const rows: Message[] = [];
    let bytes = 0;
    let scanned = 0;
    let oversizedCount = 0;
    let lastKey: PendingMessageRetryCursor | null = null;
    const request = index.openCursor(range);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) { resolve({ rows, nextCursor: null, oversizedCount }); return; }
      const row = cursor.value as Message & Record<string, unknown>;
      const cursorKey = cursor.key;
      if (!Array.isArray(cursorKey) || cursorKey.length !== 3 ||
          cursorKey[0] !== key || typeof cursorKey[1] !== "number" ||
          typeof cursorKey[2] !== "string") {
        reject(new Error("Pending message retry index has an invalid key."));
        return;
      }
      const rowBytes = (row.encrypted_content?.length ?? 0) +
        (typeof row.pending_encrypted_turn_preflight_v1 === "string"
          ? row.pending_encrypted_turn_preflight_v1.length : 0) +
        (typeof row.pending_encrypted_embed_bundle_v1 === "string"
          ? row.pending_encrypted_embed_bundle_v1.length : 0) + 1024;
      if (rows.length > 0 && bytes + rowBytes > MAX_PENDING_RETRY_PAGE_BYTES) {
        resolve({ rows, nextCursor: lastKey, oversizedCount });
        return;
      }
      if (rowBytes > MAX_PENDING_RETRY_SINGLE_ROW_BYTES) oversizedCount++;
      else {
        rows.push(row);
        bytes += rowBytes;
      }
      scanned++;
      lastKey = [cursorKey[0], cursorKey[1], cursorKey[2]];
      if (scanned >= limit) {
        resolve({ rows, nextCursor: lastKey, oversizedCount });
      } else {
        cursor.continue();
      }
    };
  });
}

/**
 * Save a single message to the database
 * Handles duplicate detection and status priority
 */
export async function saveMessage(
  dbInstance: ChatDatabaseInstance,
  message: Message,
  transaction?: IDBTransaction,
): Promise<void> {
  await dbInstance.init();

  // Normalize the input to a plain object — Svelte 5 $state() proxies and
  // their nested arrays/objects cannot be cloned by IndexedDB's structured
  // clone algorithm and throw DataCloneError on store.put(). JSON round-trip
  // strips proxy traps and yields a serializable plain object. (OPE-354)
  message = JSON.parse(JSON.stringify(message)) as Message;

  const usesExternalTransaction = !!transaction;
  console.debug(
    `[ChatDatabase] saveMessage called for ${message.message_id} (chat: ${message.chat_id}, role: ${message.role}, status: ${message.status}, external tx: ${usesExternalTransaction})`,
  );

  // DEFENSIVE: Validate message has required fields
  if (!message.message_id) {
    console.error(
      `[ChatDatabase] ❌ Cannot save message without message_id:`,
      message,
    );
    throw new Error("Message must have a message_id");
  }
  if (!message.chat_id) {
    console.error(
      `[ChatDatabase] ❌ Cannot save message without chat_id:`,
      message,
    );
    throw new Error("Message must have a chat_id");
  }

  // CRITICAL FIX: Do all async work BEFORE checking transaction state
  // Encrypt message content before storing in IndexedDB (zero-knowledge architecture)
  // Acquire critical op lock to prevent clearAll() from wiping keys between
  // getKey() and encrypt() inside encryptMessageFields().
  chatKeyManager.acquireCriticalOp();
  let encryptedMessage: Message;
  try {
    encryptedMessage = await dbInstance.encryptMessageFields(
      message,
      message.chat_id,
    );
  } finally {
    chatKeyManager.releaseCriticalOp();
  }

  // CRITICAL FIX: Check existing messages WITHOUT using the transaction (to avoid expiration)
  // We'll check for duplicates using a separate read-only transaction
  let existingMessage: Message | null = null;
  let contentDuplicate: Message | null = null;

  try {
    // CRITICAL FIX: Use SEPARATE transactions for each check operation.
    // Each check involves async decryption (getMessage -> decryptMessageFields,
    // findContentDuplicate -> getMessagesForChat -> decryptMessageFields).
    // Async operations cause the IDB transaction to auto-commit before the next
    // operation can use it, resulting in InvalidStateError.
    // Using separate transactions avoids this because each transaction only
    // needs to survive through its own async operation.
    const checkTransaction1 = await dbInstance.getTransaction(
      MESSAGES_STORE_NAME,
      "readonly",
    );
    existingMessage = await getMessage(
      dbInstance,
      message.message_id,
      checkTransaction1,
    );

    if (!existingMessage) {
      // Create a fresh transaction for the content duplicate check
      const checkTransaction2 = await dbInstance.getTransaction(
        MESSAGES_STORE_NAME,
        "readonly",
      );
      contentDuplicate = await findContentDuplicate(
        dbInstance,
        message,
        checkTransaction2,
      );
    }
  } catch (checkError) {
    // If check fails, continue anyway (will handle duplicate on put)
    // Downgraded to debug: the retry logic handles this gracefully, no action needed
    console.debug(
      `[ChatDatabase] Could not check for duplicates for ${message.message_id}:`,
      checkError,
    );
  }

  // Handle duplicates based on check results
  if (existingMessage) {
    const shouldUpdateDueToNewEncryptedFields = hasNewEncryptedFields(
      existingMessage,
      encryptedMessage,
    );
    // Only update if the new message has higher priority status
    if (
      shouldUpdateMessage(existingMessage, message) ||
      shouldUpdateDueToNewEncryptedFields
    ) {
      if (
        shouldUpdateDueToNewEncryptedFields &&
        existingMessage.status === message.status
      ) {
        console.info(
          `[ChatDatabase] ✅ Updating existing message to fill missing encrypted fields: ${message.message_id} (status: ${message.status})`,
        );
      } else {
        console.info(
          `[ChatDatabase] ✅ DUPLICATE PREVENTED - Updating existing message with higher priority status: ${message.message_id} (${existingMessage.status} -> ${message.status})`,
        );
      }
    } else {
      console.info(
        `[ChatDatabase] ✅ DUPLICATE PREVENTED - Message ${message.message_id} already exists with equal/higher priority status (${existingMessage.status}), skipping save`,
      );
      return Promise.resolve();
    }
  } else if (contentDuplicate) {
    console.warn(
      `[ChatDatabase] ⚠️ CONTENT DUPLICATE DETECTED - Found duplicate with different message_id: ${contentDuplicate.message_id} -> ${message.message_id}`,
    );
    // Update the existing message with higher priority status if applicable
    if (shouldUpdateMessage(contentDuplicate, message)) {
      console.info(
        `[ChatDatabase] ✅ DUPLICATE PREVENTED - Updating content duplicate with higher priority: ${contentDuplicate.message_id} (${contentDuplicate.status} -> ${message.status})`,
      );
      // Delete the old message - use a separate transaction
      try {
        const deleteTransaction = await dbInstance.getTransaction(
          MESSAGES_STORE_NAME,
          "readwrite",
        );
        await deleteMessage(
          dbInstance,
          contentDuplicate.message_id,
          deleteTransaction,
        );
      } catch (deleteError) {
        console.warn(
          `[ChatDatabase] Could not delete duplicate message ${contentDuplicate.message_id}:`,
          deleteError,
        );
      }
    } else {
      console.info(
        `[ChatDatabase] ✅ DUPLICATE PREVENTED - Content duplicate has equal/higher priority (${contentDuplicate.status}), skipping ${message.message_id}`,
      );
      return Promise.resolve();
    }
  } else {
    console.debug(
      `[ChatDatabase] No existing message found for ${message.message_id}, will insert as new`,
    );
  }

  const putEncryptedMessage = (
    currentTransaction: IDBTransaction,
    resolveOnComplete: boolean,
  ): Promise<void> => {
    return new Promise((resolve, reject) => {
      const store = currentTransaction.objectStore(MESSAGES_STORE_NAME);
      // Pending embed and sealed preflight journals hold the exact randomized
      // ciphertext for a same-ID retry. Preserve the current raw row's values
      // until chat_message_confirmed clears them, in the same IDB transaction.
      const getRequest = store.get(message.message_id);
      getRequest.onerror = () => reject(getRequest.error);
      getRequest.onsuccess = () => {
        const previous = getRequest.result as (Message & Record<string, unknown>) | undefined;
        const next = encryptedMessage as Message & Record<string, unknown>;
        const callJournal = previous?.call_persistence_v1 as { entries?: unknown[] } | undefined;
        if (previous?.chat_id === message.chat_id && previous.role === message.role &&
            ((Array.isArray(callJournal?.entries) && callJournal.entries.length > 0) ||
              hasNewerStoredRevision(previous, encryptedMessage))) {
          // A phased-sync snapshot may still contain the previous call revision.
          // Only the call receipt may clear its exact randomized ciphertext outbox.
          // Once confirmed, its revision still fences snapshots prepared before
          // a concurrent canonical fetch or call-message update committed.
          const preserved = store.put(previous);
          preserved.onsuccess = () => { if (!resolveOnComplete) resolve(); };
          preserved.onerror = () => reject(preserved.error);
          return;
        }
        // The caller may hold a stale decrypted copy from before ACK cleanup.
        // Only the current raw row may authorize retaining this field.
        for (const field of ["pending_encrypted_embed_bundle_v1", "pending_encrypted_turn_preflight_v1"]) {
          delete next[field];
          if (previous?.chat_id === message.chat_id &&
              Object.prototype.hasOwnProperty.call(previous, field)) {
            next[field] = previous[field];
          }
        }
        // The numeric secondary-index marker follows the winning raw journal,
        // never a stale decrypted caller or a pre-ACK copy.
        if (typeof next.pending_encrypted_turn_preflight_v1 === "string") {
          next.pending_turn_preflight_v1 = 1;
        } else {
          delete next.pending_turn_preflight_v1;
        }
        const request = store.put(next);
        request.onsuccess = () => {
          console.debug(
            `[ChatDatabase] ✅ Encrypted message saved/updated successfully (queued): ${message.message_id} (chat: ${message.chat_id})`,
          );
          if (!resolveOnComplete) resolve();
        };
        request.onerror = () => {
          console.error(
            `[ChatDatabase] ❌ Error in message store.put operation for ${message.message_id}:`,
            request.error,
          );
          reject(request.error);
        };
      };

      if (resolveOnComplete) {
        currentTransaction.oncomplete = () => {
          console.debug(
            `[ChatDatabase] ✅ Transaction for saveMessage completed successfully for message: ${message.message_id}`,
          );
          resolve();
        };
        currentTransaction.onerror = () => {
          console.error(
            `[ChatDatabase] ❌ Transaction for saveMessage failed for message: ${message.message_id}, Error:`,
            currentTransaction.error,
          );
          reject(currentTransaction.error);
        };
        currentTransaction.onabort = () => reject(currentTransaction.error ?? new Error("Message save aborted"));
      }
    });
  };

  const isInvalidStateError = (error: unknown): boolean => {
    return (
      error instanceof Error &&
      (error.name === "InvalidStateError" ||
        error.message.includes("transaction"))
    );
  };

  const saveWithRetry = async (): Promise<void> => {
    // CRITICAL FIX: Check if external transaction is still active before using it
    if (usesExternalTransaction && transaction) {
      try {
        // Try to access the transaction's mode - if it throws, the transaction is finished
        void transaction.mode;
        if (transaction.error !== null) {
          throw new Error(`Transaction has error: ${transaction.error}`);
        }
      } catch (_error) {
        console.debug(
          `[ChatDatabase] External transaction expired for message ${message.message_id}, retrying with new transaction`,
        );
        // Re-check priority before retrying with a new transaction to prevent
        // stale status overwrites (same fix as in the catch block below)
        try {
          const recheckTx = await dbInstance.getTransaction(
            MESSAGES_STORE_NAME,
            "readonly",
          );
          const currentInDb = await getMessage(
            dbInstance,
            message.message_id,
            recheckTx,
          );
          if (currentInDb && !shouldUpdateMessage(currentInDb, message)) {
            console.info(
              `[ChatDatabase] ✅ STALE WRITE PREVENTED on external tx retry - message ${message.message_id} already has status (${currentInDb.status}), skipping write of status (${message.status})`,
            );
            return;
          }
        } catch (recheckError) {
          console.debug(
            `[ChatDatabase] Could not re-check message priority before external tx retry:`,
            recheckError,
          );
        }
        const newTransaction = await dbInstance.getTransaction(
          MESSAGES_STORE_NAME,
          "readwrite",
        );
        return putEncryptedMessage(newTransaction, true);
      }
    }

    const currentTransaction =
      transaction ||
      (await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readwrite"));

    // CRITICAL FIX: Check transaction state one more time right before using it
    try {
      await putEncryptedMessage(currentTransaction, !usesExternalTransaction);
    } catch (error) {
      // Transaction is no longer active (InvalidStateError or similar)
      if (isInvalidStateError(error)) {
        console.debug(
          `[ChatDatabase] Transaction expired for message ${message.message_id}, retrying with new transaction`,
        );
        // CRITICAL FIX: Before retrying, re-check if a higher-priority status
        // has been written to IDB by a concurrent save (e.g., 'synced' was
        // written while this 'processing' write was delayed by transaction expiry).
        // Without this check, the retry can overwrite a newer status with a stale one,
        // causing the "Processing..." indicator to flicker.
        try {
          const recheckTx = await dbInstance.getTransaction(
            MESSAGES_STORE_NAME,
            "readonly",
          );
          const currentInDb = await getMessage(
            dbInstance,
            message.message_id,
            recheckTx,
          );
          if (currentInDb && !shouldUpdateMessage(currentInDb, message)) {
            console.info(
              `[ChatDatabase] ✅ STALE WRITE PREVENTED on retry - message ${message.message_id} already has equal/higher priority status in IDB (${currentInDb.status}), skipping write of status (${message.status})`,
            );
            return;
          }
        } catch (recheckError) {
          // If the re-check fails, proceed with the write (better to write than lose data)
          console.debug(
            `[ChatDatabase] Could not re-check message priority before retry:`,
            recheckError,
          );
        }

        const newTransaction = await dbInstance.getTransaction(
          MESSAGES_STORE_NAME,
          "readwrite",
        );
        await putEncryptedMessage(newTransaction, true);
      } else {
        // Some other error - rethrow it
        console.error(
          `[ChatDatabase] Unexpected error in saveMessage for message ${message.message_id}:`,
          error,
        );
        throw error;
      }
    }
  };

  await writeWithQuotaRetry(
    saveWithRetry,
    () => enforceOfflineCacheBudget(dbInstance, true),
    async () => {
      const { notificationStore } = await import("../../stores/notificationStore");
      notificationStore.error(
        "Browser storage is full. This change was not saved for offline use. Free space and try again.",
        undefined, true, "offline-save-unavailable",
      );
    },
    !usesExternalTransaction,
    async () => {
      try {
        const recheckTx = await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readonly");
        const current = await getMessage(dbInstance, message.message_id, recheckTx);
        if (current && !shouldUpdateMessage(current, message) &&
            !hasNewEncryptedFields(current, encryptedMessage)) return;
      } catch (recheckError) {
        console.debug("[ChatDatabase] Could not recheck message after quota trim:", recheckError);
      }
      const retryTransaction = await dbInstance.getTransaction(MESSAGES_STORE_NAME, "readwrite");
      await putEncryptedMessage(retryTransaction, true);
    },
  );
  invalidateRecentChatWindow(message.chat_id, 'message');
}

/**
 * Overwrite a message by primary key after encrypting it with the normal chat key path.
 * Use only when a same-ID local placeholder is known stale and the incoming message is
 * authoritative; regular saves should keep duplicate/status protection.
 */
export async function replaceMessageById(
  dbInstance: ChatDatabaseInstance,
  message: Message,
  options: {
    allowedExistingStatuses?: Message["status"][];
    expectedExistingRole?: Message["role"];
  } = {},
): Promise<boolean> {
  await dbInstance.init();

  message = JSON.parse(JSON.stringify(message)) as Message;

  if (!message.message_id) {
    throw new Error("Message must have a message_id");
  }
  if (!message.chat_id) {
    throw new Error("Message must have a chat_id");
  }

  chatKeyManager.acquireCriticalOp();
  let encryptedMessage: Message;
  try {
    encryptedMessage = await dbInstance.encryptMessageFields(
      message,
      message.chat_id,
    );
  } finally {
    chatKeyManager.releaseCriticalOp();
  }

  const transaction = await dbInstance.getTransaction(
    MESSAGES_STORE_NAME,
    "readwrite",
  );
  return new Promise<boolean>((resolve, reject) => {
    const store = transaction.objectStore(MESSAGES_STORE_NAME);
    const getRequest = store.get(message.message_id);
    let replaced = false;

    getRequest.onsuccess = () => {
      const current = getRequest.result as Message | undefined;
      const statusAllowed =
        !current ||
        !options.allowedExistingStatuses ||
        options.allowedExistingStatuses.includes(current.status);
      const roleAllowed =
        !current ||
        !options.expectedExistingRole ||
        current.role === options.expectedExistingRole;

      if (!statusAllowed || !roleAllowed) {
        console.warn(
          `[ChatDatabase] replaceMessageById skipped ${message.message_id}: current row no longer matches replacement guard`,
        );
        return;
      }

      const putRequest = store.put(encryptedMessage);
      putRequest.onsuccess = () => {
        replaced = true;
      };
      putRequest.onerror = () => {
        reject(putRequest.error);
      };
    };
    getRequest.onerror = () => {
      reject(getRequest.error);
    };
    transaction.oncomplete = () => {
      if (replaced) invalidateRecentChatWindow(message.chat_id, 'message');
      resolve(replaced);
    };
    transaction.onerror = () => {
      reject(transaction.error);
    };
    transaction.onabort = () => {
      reject(
        new Error(`Transaction aborted for replaceMessageById(${message.message_id})`),
      );
    };
  });
}

/**
 * Batch save multiple messages efficiently in a single transaction
 * This method prevents transaction auto-commit issues by:
 * 1. Checking for duplicates BEFORE creating the transaction
 * 2. Encrypting all messages BEFORE creating the transaction
 * 3. Queuing all put operations synchronously (no await between them)
 *
 * @param dbInstance The ChatDatabase instance
 * @param messages Array of messages to save
 * @returns Promise that resolves when all messages are saved
 */
export async function batchSaveMessages(
  dbInstance: ChatDatabaseInstance,
  messages: Message[],
): Promise<void> {
  await dbInstance.init();

  if (messages.length === 0) {
    return Promise.resolve();
  }

  console.debug(
    `[ChatDatabase] batchSaveMessages: Processing ${messages.length} messages`,
  );

  // Step 1: Validate all messages have required fields
  const validMessages: Message[] = [];
  for (const message of messages) {
    if (!message.message_id) {
      console.error(
        `[ChatDatabase] ❌ Skipping message without message_id:`,
        message,
      );
      continue;
    }
    if (!message.chat_id) {
      console.error(
        `[ChatDatabase] ❌ Skipping message without chat_id:`,
        message,
      );
      continue;
    }
    validMessages.push(message);
  }

  if (validMessages.length === 0) {
    console.warn(`[ChatDatabase] No valid messages to save after validation`);
    return Promise.resolve();
  }

  // Step 2: Check for duplicates by fetching all existing messages in a single transaction
  // CRITICAL FIX: Use individual read transactions for each check to avoid transaction auto-commit
  // Since each check is quick, this is more reliable than trying to keep one transaction alive
  const messagesToSkip = new Set<string>();
  const existingMessagesMap = new Map<string, Message>();

  // Check for existing messages using per-message transactions.
  //
  // CRITICAL: A shared IDB transaction CANNOT be used across concurrent async operations.
  // IDB transactions auto-commit as soon as their event queue drains — i.e. whenever the
  // JS event loop gets control back between IDB requests. Each getMessage() call awaits
  // decryptMessageFields() (an async crypto operation) inside its onsuccess callback,
  // which drains the transaction's queue and triggers auto-commit. Any concurrent call
  // using the same transaction after that point throws:
  //   "InvalidStateError: Failed to execute 'objectStore' on 'IDBTransaction':
  //    The transaction has finished."
  //
  // The only safe approach for concurrent async reads is one transaction per operation.
  const existingMessageChecks = await Promise.all(
    validMessages.map(async (message) => {
      try {
        // Each message gets its own fresh transaction so async decryption inside
        // getMessage() cannot interfere with sibling calls.
        const txn = await dbInstance.getTransaction(
          MESSAGES_STORE_NAME,
          "readonly",
        );
        const existingMessage = await getMessage(
          dbInstance,
          message.message_id,
          txn,
        );
        return { message, existingMessage };
      } catch {
        // Silently treat as "not found" — the put() below will handle it correctly
        // since IndexedDB put() is an upsert operation (insert or update).
        return { message, existingMessage: null };
      }
    }),
  );

  // Process duplicate checks in memory
  for (const { message, existingMessage } of existingMessageChecks) {
    if (existingMessage) {
      existingMessagesMap.set(message.message_id, existingMessage);

      // Check if we should update
      if (shouldUpdateMessage(existingMessage, message)) {
        console.debug(
          `[ChatDatabase] batchSaveMessages: Will update existing message ${message.message_id} with higher priority`,
        );
        // Will save below - don't skip
      } else {
        console.debug(
          `[ChatDatabase] batchSaveMessages: Skipping ${message.message_id} - already exists with equal/higher priority`,
        );
        messagesToSkip.add(message.message_id);
      }
    } else {
      // Check for content duplicates only if message doesn't exist by ID
      // Note: Content duplicate checking is expensive, so we skip it in batch operations
      // Duplicate cleanup will handle content duplicates later
      // For now, we'll save the message and let duplicate cleanup handle it
    }
  }

  // Step 3: Encrypt all messages that need to be saved (BEFORE creating write transaction)
  const messagesToEncrypt = validMessages.filter(
    (msg) => !messagesToSkip.has(msg.message_id),
  );
  const encryptionPromises = messagesToEncrypt.map(async (message) => {
    const encrypted = await dbInstance.encryptMessageFields(
      message,
      message.chat_id,
    );
    return { message, encrypted };
  });

  const preparedMessages = await Promise.all(encryptionPromises);

  if (preparedMessages.length === 0) {
    console.debug(
      `[ChatDatabase] batchSaveMessages: No messages to save after duplicate checking`,
    );
    return Promise.resolve();
  }

  // Step 4: Create write transaction and queue all operations synchronously
  let writeTransaction: IDBTransaction;
  try {
    writeTransaction = await dbInstance.getTransaction(
      MESSAGES_STORE_NAME,
      "readwrite",
    );
  } catch (error) {
    console.error(
      `[ChatDatabase] batchSaveMessages: Error creating transaction:`,
      error,
    );
    throw error;
  }

  return new Promise((resolve, reject) => {
    const store = writeTransaction.objectStore(MESSAGES_STORE_NAME);

    // Queue every read synchronously. Each callback queues its matching put
    // in this same transaction, preserving pending ciphertext retry journals
    // when phased sync replaces an existing message row by ID.
    for (const { message, encrypted } of preparedMessages) {
      const getRequest = store.get(message.message_id);
      getRequest.onerror = () => {
        console.error(`[ChatDatabase] batchSaveMessages: Read failed for ${message.message_id}:`, getRequest.error);
      };
      getRequest.onsuccess = () => {
        const previous = getRequest.result as (Message & Record<string, unknown>) | undefined;
        const next = encrypted as Message & Record<string, unknown>;
        const callJournal = previous?.call_persistence_v1 as { entries?: unknown[] } | undefined;
        if (previous?.chat_id === message.chat_id && previous.role === message.role &&
            ((Array.isArray(callJournal?.entries) && callJournal.entries.length > 0) ||
              hasNewerStoredRevision(previous, encrypted))) {
          const preserved = store.put(previous);
          preserved.onerror = () => {
            console.error(`[ChatDatabase] batchSaveMessages: Pending call row preservation failed for ${message.message_id}:`, preserved.error);
          };
          return;
        }
        for (const field of ["pending_encrypted_embed_bundle_v1", "pending_encrypted_turn_preflight_v1"]) {
          delete next[field];
          if (previous?.chat_id === message.chat_id &&
              Object.prototype.hasOwnProperty.call(previous, field)) {
            next[field] = previous[field];
          }
        }
        if (typeof next.pending_encrypted_turn_preflight_v1 === "string") {
          next.pending_turn_preflight_v1 = 1;
        } else {
          delete next.pending_turn_preflight_v1;
        }
        const putRequest = store.put(next);
        putRequest.onerror = () => {
          console.error(`[ChatDatabase] batchSaveMessages: Write failed for ${message.message_id}:`, putRequest.error);
        };
      };
    }

    console.debug(
      `[ChatDatabase] batchSaveMessages: Queued ${preparedMessages.length} guarded writes in transaction`,
    );

    // Wait for transaction to complete
    writeTransaction.oncomplete = () => {
      console.debug(
        `[ChatDatabase] batchSaveMessages: Transaction completed successfully for ${preparedMessages.length} messages`,
      );
      for (const chatId of new Set(preparedMessages.map(({ message }) => message.chat_id))) invalidateRecentChatWindow(chatId, 'message');
      resolve();
    };

    writeTransaction.onerror = () => {
      console.error(
        `[ChatDatabase] batchSaveMessages: Transaction error:`,
        writeTransaction.error,
      );
      reject(writeTransaction.error);
    };

    writeTransaction.onabort = () => {
      console.error(`[ChatDatabase] batchSaveMessages: Transaction aborted`);
      reject(writeTransaction.error ?? new Error("Transaction aborted"));
    };

  });
}

/**
 * Update only the status field of a message in-place, without touching encrypted content.
 *
 * WHY THIS EXISTS — THE BUG IT FIXES:
 * The naive approach of `getMessage() → mutate → saveMessage()` causes silent data
 * corruption when changing a message status to "synced". `saveMessage()` calls
 * `encryptMessageFields()`, which calls `getOrGenerateChatKey()`. If the chat key
 * has been evicted from the in-memory cache (a real race condition during the
 * new-chat flow), a NEW random key is generated and the message is re-encrypted with
 * it. But `encrypted_chat_key` on the chat still holds the original key. From that
 * point forward, decryption fails with "[Content decryption failed]" on the sending
 * device, while other devices (which only ever see the server-persisted copy encrypted
 * with the correct original key) work fine.
 *
 * THE FIX:
 * Read the raw IndexedDB record (no decryption), patch only `status`, and write it
 * back. The encrypted fields are never touched, so no key is ever needed.
 *
 * @param dbInstance - Reference to the ChatDatabase instance
 * @param message_id - The ID of the message to update
 * @param newStatus - The new status to set
 * @returns Promise that resolves when the update is complete
 */
export async function updateMessageStatus(
  dbInstance: ChatDatabaseInstance,
  message_id: string,
  newStatus: Message["status"],
): Promise<void> {
  await dbInstance.init();

  console.debug(
    `[ChatDatabase] updateMessageStatus: ${message_id} → "${newStatus}" (raw in-place, no re-encryption)`,
  );

  if (!dbInstance.db) {
    throw new Error("Database not initialized");
  }

  return new Promise((resolve, reject) => {
    // Open a single readwrite transaction that covers the full get→patch→put cycle.
    // All operations are queued synchronously inside the transaction callbacks, so
    // the transaction stays alive until oncomplete fires.
    const tx = (dbInstance.db as IDBDatabase).transaction(
      MESSAGES_STORE_NAME,
      "readwrite",
    );
    const store = tx.objectStore(MESSAGES_STORE_NAME);
    let updatedChatId: string | null = null;

    // Step 1: Read the raw (still-encrypted) record by primary key.
    const getRequest = store.get(message_id);

    getRequest.onsuccess = () => {
      const rawRecord = getRequest.result as Message | undefined;

      if (!rawRecord) {
        // Message doesn't exist yet. This can happen if the confirmation arrives
        // before the message was saved locally (very rare). Nothing to do.
        console.warn(
          `[ChatDatabase] updateMessageStatus: message ${message_id} not found in IndexedDB, skipping status update`,
        );
        resolve();
        return;
      }

      // Guard: never overwrite 'waiting_for_user' with 'synced' or 'delivered'.
      // 'waiting_for_user' is a terminal client-side display state (credits rejection,
      // permissions request). The server doesn't persist this state — Directus has no status
      // column, so phased sync messages arrive with 'delivered' as default, and
      // chat_message_confirmed events use 'synced'. Either would clobber the client state
      // and hide the Buy Credits button / header banner.
      if (
        rawRecord.status === "waiting_for_user" &&
        (newStatus === "synced" || newStatus === "delivered")
      ) {
        console.debug(
          `[ChatDatabase] updateMessageStatus: preserving 'waiting_for_user' for message ${message_id} — skipping ${newStatus} overwrite`,
        );
        resolve();
        return;
      }
      if (rawRecord.status === "queued" &&
          (newStatus === "synced" || newStatus === "delivered")) {
        resolve();
        return;
      }

      // Step 2: Patch only the status field. Encrypted fields are untouched.
      const patched: Message = { ...rawRecord, status: newStatus };
      updatedChatId = rawRecord.chat_id;
      invalidateRecentChatWindow(updatedChatId, 'message');

      // Step 3: Write the patched record back using the SAME transaction.
      // Queueing the put synchronously in the onsuccess callback keeps the
      // transaction alive — no async gap means no auto-commit.
      const putRequest = store.put(patched);

      putRequest.onerror = () => {
        console.error(
          `[ChatDatabase] updateMessageStatus: put failed for ${message_id}:`,
          putRequest.error,
        );
        // Don't reject here — let tx.onerror handle it to avoid double-rejection.
      };
    };

    getRequest.onerror = () => {
      console.error(
        `[ChatDatabase] updateMessageStatus: get failed for ${message_id}:`,
        getRequest.error,
      );
      // Let tx.onerror handle the rejection.
    };

    tx.oncomplete = () => {
      if (updatedChatId) invalidateRecentChatWindow(updatedChatId, 'message');
      console.debug(
        `[ChatDatabase] updateMessageStatus: ✅ status updated to "${newStatus}" for ${message_id}`,
      );
      resolve();
    };

    tx.onerror = () => {
      console.error(
        `[ChatDatabase] updateMessageStatus: ❌ transaction error for ${message_id}:`,
        tx.error,
      );
      reject(tx.error);
    };

    tx.onabort = () => {
      console.error(
        `[ChatDatabase] updateMessageStatus: ❌ transaction aborted for ${message_id}`,
      );
      reject(
        new Error(`Transaction aborted for updateMessageStatus(${message_id})`),
      );
    };
  });
}

/**
 * Update one or more non-encrypted fields on an existing message without touching
 * any encrypted content or triggering key operations.
 *
 * Use this for writing metadata fields (e.g. thinking_content, thinking_signature,
 * thinking_token_count, has_thinking) onto an existing message that was already
 * encrypted and stored. Like updateMessageStatus(), this reads the raw IndexedDB
 * record, merges only the provided fields, and writes it back — no encryption or
 * key operations involved.
 *
 * NEVER pass encrypted fields (encrypted_content, encrypted_category,
 * encrypted_sender_name, encrypted_model_name, encrypted_thinking_content) in
 * `fields` — those must go through the normal saveMessage() encryption path.
 * This function is for plaintext metadata fields only.
 *
 * If the message does not exist yet, a minimal placeholder is created by merging
 * `fields` with a minimal record seeded from `fallback` (required when the message
 * may not be in IndexedDB yet, e.g. during early streaming).
 *
 * @param dbInstance - Reference to the ChatDatabase instance
 * @param message_id - The ID of the message to update
 * @param fields - Partial Message with only the non-encrypted fields to set
 * @param fallback - Optional minimal record used when the message doesn't exist yet
 */
export async function updateMessageRawFields(
  dbInstance: ChatDatabaseInstance,
  message_id: string,
  fields: Partial<Message>,
  fallback?: Omit<Message, "message_id">,
): Promise<void> {
  await dbInstance.init();

  console.debug(
    `[ChatDatabase] updateMessageRawFields: ${message_id} → patching fields: ${Object.keys(fields).join(", ")} (raw in-place, no re-encryption)`,
  );

  if (!dbInstance.db) {
    throw new Error("Database not initialized");
  }

  return new Promise((resolve, reject) => {
    const tx = (dbInstance.db as IDBDatabase).transaction(
      MESSAGES_STORE_NAME,
      "readwrite",
    );
    const store = tx.objectStore(MESSAGES_STORE_NAME);
    let updatedChatId: string | null = null;
    let previousChatId: string | null = null;

    const getRequest = store.get(message_id);

    getRequest.onsuccess = () => {
      const rawRecord = getRequest.result as Message | undefined;

      let patched: Message;
      if (rawRecord) {
        // Message already exists — merge fields on top of the existing raw record.
        // Encrypted fields in rawRecord are preserved untouched.
        patched = { ...rawRecord, ...fields };
      } else if (fallback) {
        // Message doesn't exist yet — create a minimal placeholder from the fallback.
        patched = { message_id, ...fallback, ...fields };
      } else {
        // No existing record and no fallback — nothing we can safely do.
        console.warn(
          `[ChatDatabase] updateMessageRawFields: message ${message_id} not found and no fallback provided, skipping`,
        );
        resolve();
        return;
      }

      updatedChatId = patched.chat_id;
      previousChatId = rawRecord?.chat_id ?? null;
      invalidateRecentChatWindow(updatedChatId, 'message');
      if (previousChatId && previousChatId !== updatedChatId) invalidateRecentChatWindow(previousChatId, 'message');

      const putRequest = store.put(patched);
      putRequest.onerror = () => {
        console.error(
          `[ChatDatabase] updateMessageRawFields: put failed for ${message_id}:`,
          putRequest.error,
        );
      };
    };

    getRequest.onerror = () => {
      console.error(
        `[ChatDatabase] updateMessageRawFields: get failed for ${message_id}:`,
        getRequest.error,
      );
    };

    tx.oncomplete = () => {
      if (updatedChatId) invalidateRecentChatWindow(updatedChatId, 'message');
      if (previousChatId && previousChatId !== updatedChatId) invalidateRecentChatWindow(previousChatId, 'message');
      console.debug(
        `[ChatDatabase] updateMessageRawFields: ✅ fields updated for ${message_id}`,
      );
      resolve();
    };

    tx.onerror = () => {
      console.error(
        `[ChatDatabase] updateMessageRawFields: ❌ transaction error for ${message_id}:`,
        tx.error,
      );
      reject(tx.error);
    };

    tx.onabort = () => {
      console.error(
        `[ChatDatabase] updateMessageRawFields: ❌ transaction aborted for ${message_id}`,
      );
      reject(
        new Error(
          `Transaction aborted for updateMessageRawFields(${message_id})`,
        ),
      );
    };
  });
}

/** Apply a server-committed queued revision to a stored ciphertext row atomically. */
export async function applyQueuedMessageRevision(
  dbInstance: ChatDatabaseInstance,
  chatId: string,
  messageId: string,
  revision: number,
  mode: "follow_up" | "steer",
  encryptedContent?: string,
  encryptedPiiMappings?: string | null,
): Promise<boolean> {
  if (!Number.isSafeInteger(revision) || revision < 1) return false;
  await dbInstance.init();
  if (!dbInstance.db) throw new Error("Database not initialized");
  return new Promise((resolve, reject) => {
    const tx = dbInstance.db!.transaction(MESSAGES_STORE_NAME, "readwrite");
    const store = tx.objectStore(MESSAGES_STORE_NAME);
    let applied = false;
    const request = store.get(messageId);
    request.onsuccess = () => {
      const row = request.result as Message | undefined;
      if (!row || row.chat_id !== chatId || row.role !== "user") return;
      if (row.queue_dispatch_status === "processing" || row.queue_dispatch_status === "paused") return;
      const previous = row.queue_revision ?? 0;
      if (revision > previous + 1 && !encryptedContent) return; // Never advance past an unseen content edit.
      if (previous > revision ||
          (previous === revision && row.status === "queued" && row.queue_mode === mode && !encryptedContent)) return;
      const updated: Message = {
        ...row,
        status: "queued",
        queue_revision: revision,
        queue_mode: mode,
        queue_dispatch_status: "queued",
        queue_dispatch_mode: mode,
        ...(encryptedContent ? { encrypted_content: encryptedContent } : {}),
        ...(encryptedPiiMappings !== undefined
          ? { encrypted_pii_mappings: encryptedPiiMappings ?? undefined } : {}),
      };
      // A decrypted `content` field must never shadow the new ciphertext in IDB.
      delete updated.content;
      delete updated.pii_mappings;
      store.put(updated);
      applied = true;
      invalidateRecentChatWindow(chatId, 'message');
    };
    request.onerror = () => reject(request.error);
    tx.oncomplete = () => { if (applied) invalidateRecentChatWindow(chatId, 'message'); resolve(applied); };
    tx.onerror = () => reject(tx.error);
    tx.onabort = () => reject(tx.error ?? new Error("Queued revision transaction aborted"));
  });
}

/**
 * Delete a specific message by message_id
 * NOTE: Can be called during init() cleanup, so may need to handle uninitialized DB
 */
export async function deleteMessage(
  dbInstance: ChatDatabaseInstance,
  message_id: string,
  transaction?: IDBTransaction,
): Promise<void> {
  return new Promise((resolve, reject) => {
    if (!dbInstance.db) {
      reject(new Error("Database not initialized"));
      return;
    }

    const currentTransaction =
      transaction ||
      dbInstance.db.transaction(MESSAGES_STORE_NAME, "readwrite");
    const store = currentTransaction.objectStore(MESSAGES_STORE_NAME);
    let deletedChatId: string | null = null;
    let deleteQueued = false;
    const readRequest = store.get(message_id);
    readRequest.onsuccess = () => {
      deletedChatId = (readRequest.result as Message | undefined)?.chat_id ?? null;
      // Fence an in-flight cold read before its old snapshot can be published.
      if (deletedChatId) invalidateRecentChatWindow(deletedChatId, 'message');
      else invalidateRecentChatWindowForMessage(message_id);
      const deleteRequest = store.delete(message_id);
      deleteRequest.onsuccess = () => {
        deleteQueued = true;
        console.debug("[ChatDatabase] Message deleted successfully:", message_id);
        if (transaction) resolve();
      };
      deleteRequest.onerror = () => reject(deleteRequest.error);
    };
    readRequest.onerror = () => reject(readRequest.error);
    currentTransaction.addEventListener("complete", () => {
      if (deleteQueued) {
        if (deletedChatId) invalidateRecentChatWindow(deletedChatId, 'message');
        else invalidateRecentChatWindowForMessage(message_id);
      }
      if (!transaction) resolve();
    }, { once: true });
    currentTransaction.addEventListener("error", () => reject(currentTransaction.error), { once: true });
    currentTransaction.addEventListener("abort", () => reject(currentTransaction.error), { once: true });
  });
}

// ============================================================================
// DUPLICATE CLEANUP
// ============================================================================

/**
 * Clean up duplicate messages by keeping the one with highest priority status
 * This method should be called during initialization to clean up existing duplicates
 */
export async function cleanupDuplicateMessages(
  dbInstance: ChatDatabaseInstance,
): Promise<void> {
  // NOTE: Do NOT call dbInstance.init() here! This method is called FROM init()
  // and calling it again would create a deadlock waiting for itself to finish.
  console.debug("[ChatDatabase] Starting duplicate message cleanup...");

  try {
    // Get all messages grouped by chat
    // Pass duringInit=true since this is called from init()
    const allMessages = await getAllMessages(dbInstance, true);
    const messagesByChat = new Map<string, Message[]>();

    // Group messages by chat_id
    allMessages.forEach((msg) => {
      if (!messagesByChat.has(msg.chat_id)) {
        messagesByChat.set(msg.chat_id, []);
      }
      messagesByChat.get(msg.chat_id)!.push(msg);
    });

    let duplicatesRemoved = 0;

    // Process each chat's messages for duplicates
    const chatIds = Array.from(messagesByChat.keys());
    for (const chatId of chatIds) {
      const messages = messagesByChat.get(chatId)!;
      const processedMessages = new Set<string>();

      for (let i = 0; i < messages.length; i++) {
        const currentMessage = messages[i];

        if (processedMessages.has(currentMessage.message_id)) {
          continue; // Already processed
        }

        // Find all duplicates of this message (same message_id or content duplicates)
        const duplicates = [currentMessage];

        for (let j = i + 1; j < messages.length; j++) {
          const otherMessage = messages[j];

          if (processedMessages.has(otherMessage.message_id)) {
            continue; // Already processed
          }

          // Only match on exact message_id — content-based matching was removed because it
          // could falsely delete legitimate messages that happen to share the same encrypted_content
          // within a time window, shrinking the local count below server count and triggering
          // perpetual re-sync loops ("DATA INCONSISTENCY DETECTED" on every reload).
          if (currentMessage.message_id === otherMessage.message_id) {
            duplicates.push(otherMessage);
            processedMessages.add(otherMessage.message_id);
          }
        }

        if (duplicates.length > 1) {
          console.debug(
            `[ChatDatabase] Found ${duplicates.length} duplicates for message ${currentMessage.message_id} in chat ${chatId}`,
          );

          // Use the shared STATUS_PRIORITY map (not a local copy) so priority ordering
          // stays consistent with shouldUpdateMessage() and the rest of the sync pipeline.
          const bestMessage = duplicates.reduce((best, current) => {
            const bestPriority = STATUS_PRIORITY[best.status] ?? 0;
            const currentPriority = STATUS_PRIORITY[current.status] ?? 0;
            return currentPriority > bestPriority ? current : best;
          });

          // Delete all duplicates except the best one
          const toDelete = duplicates.filter((msg) => msg !== bestMessage);
          for (const duplicate of toDelete) {
            await deleteMessage(dbInstance, duplicate.message_id);
            duplicatesRemoved++;
          }

          console.debug(
            `[ChatDatabase] Kept message ${bestMessage.message_id} with status '${bestMessage.status}', removed ${toDelete.length} duplicates`,
          );
        }

        processedMessages.add(currentMessage.message_id);
      }
    }

    console.debug(
      `[ChatDatabase] Duplicate cleanup completed. Removed ${duplicatesRemoved} duplicate messages.`,
    );
  } catch (error) {
    console.error("[ChatDatabase] Error during duplicate cleanup:", error);
  }
}

import type { Chat } from '../types/chat';

/** Already encrypted optional metadata is patched in one transaction. No
 * decryption/key await can overwrite a concurrent draft, queue or sync write. */
export async function persistGeneratedChatMetadata(
  database: { db: IDBDatabase | null; CHATS_STORE_NAME: string; init(): Promise<void> },
  baseline: Chat,
  patch: Partial<Chat>,
  isCurrent: () => boolean,
  filterPatch: (patch: Partial<Chat>) => Partial<Chat> = (value) => value,
): Promise<Chat | null> {
  if (!database.db) await database.init();
  if (!database.db || !isCurrent()) return null;
  return new Promise((resolve, reject) => {
    const transaction = database.db!.transaction(database.CHATS_STORE_NAME, 'readwrite');
    const store = transaction.objectStore(database.CHATS_STORE_NAME);
    let updated: Chat | null = null;
    const request = store.get(baseline.chat_id);
    request.onsuccess = () => {
      const latest = request.result as Chat | undefined;
      if (!latest || !isCurrent() || latest.encrypted_chat_key !== baseline.encrypted_chat_key) return;
      const accepted = { ...filterPatch(patch) };
      if (accepted.metadata_v !== undefined && (latest.metadata_v ?? 0) > accepted.metadata_v) {
        updated = latest;
        return;
      }
      if (latest.title_v !== baseline.title_v) {
        delete accepted.encrypted_title; delete accepted.title_v;
      }
      if (latest.encrypted_chat_summary !== baseline.encrypted_chat_summary) delete accepted.encrypted_chat_summary;
      updated = { ...latest, ...accepted };
      store.put(updated);
    };
    transaction.oncomplete = () => resolve(updated);
    transaction.onerror = () => reject(transaction.error ?? new Error('Generated chat metadata write failed'));
    transaction.onabort = () => reject(transaction.error ?? new Error('Generated chat metadata write aborted'));
  });
}

/** Thin browser primitives. Rust chooses auth, ownership and persistence policy. */
export const AUTH_REFRESH_LOCK = "openmates:auth-session-refresh";

declare const refreshLeaseBrand: unique symbol;
export interface AuthRefreshLease { readonly [refreshLeaseBrand]: true }
declare const effectLeaseBrand: unique symbol;
export interface AuthRefreshEffectLease { readonly [effectLeaseBrand]: true }

type LeaseState = { active: boolean; signal: AbortSignal; current: () => void;
  controller: AbortController; pending: Set<Promise<unknown>> };
type LockState = LeaseState & { locks: LockManager };
type EffectState = LeaseState & { issuer: object; operationId: string };
const lockLeases = new WeakMap<object, LockState>();
const effectLeases = new WeakMap<object, EffectState>();
function checkLease(state: LeaseState): void {
  if (!state.active || state.signal.aborted || state.controller.signal.aborted) throw new Error("invalidated_snapshot");
  state.current();
}
function opaqueLease(): object {
  // An own function makes structured clone fail; WeakMaps reject every copy.
  return Object.freeze({ checkpoint: () => undefined });
}
function runLeased<T>(state: LeaseState, operation: (signal: AbortSignal) => Promise<T>, checkResult = true): Promise<T> {
  checkLease(state);
  const pending = Promise.resolve().then(() => { checkLease(state); return operation(state.controller.signal); })
    .then(result => { if (checkResult) checkLease(state); return result; });
  state.pending.add(pending);
  void pending.then(() => state.pending.delete(pending), () => state.pending.delete(pending));
  return pending;
}
async function revokeLease(state: LeaseState): Promise<void> {
  state.active = false;
  state.controller.abort();
  // Aborting a caller does not attest IDB termination. Every registered effect
  // resolves/rejects only after its actual transaction terminal event.
  while (state.pending.size) await Promise.allSettled([...state.pending]);
}
function makeState(signal: AbortSignal, current: () => void): LeaseState {
  const state: LeaseState = { active: true, signal, current, controller: new AbortController(), pending: new Set() };
  checkLease(state);
  return state;
}

/** Existing WebLock, with local inherited ownership only; no auth policy. */
export async function withAuthRefreshLock<T>(locks: LockManager, signal: AbortSignal,
  operation: (lease: AuthRefreshLease) => Promise<T>,
  options: { lease?: AuthRefreshLease; current?: () => void } = {}): Promise<T> {
  const current = options.current ?? (() => undefined);
  if (signal.aborted) throw new Error("cancelled");
  current();
  const inherited = options.lease;
  if (inherited !== undefined) {
    const state = lockLeases.get(inherited);
    if (!state || state.locks !== locks) throw new Error("invalidated_snapshot");
    return runLeased(state, async () => {
      if (signal.aborted) throw new Error("cancelled");
      current();
      const result = await operation(inherited);
      if (signal.aborted) throw new Error("cancelled");
      current();
      return result;
    });
  }
  if (!locks || typeof locks.request !== "function") throw new Error("auth_refresh_lock_unavailable");
  return await locks.request(AUTH_REFRESH_LOCK, { mode: "exclusive", signal }, async () => {
    if (signal.aborted) throw new Error("cancelled");
    current();
    const state: LockState = { ...makeState(signal, current), locks };
    const lease = opaqueLease() as AuthRefreshLease;
    lockLeases.set(lease, state);
    const abort = () => state.controller.abort();
    signal.addEventListener("abort", abort, { once: true });
    // Legacy callers receive their returned resource even after cancellation,
    // so their existing owner can dispose it. Stronger scoped callers opt into
    // a post-effect validity check; reverse IO leases always require that check.
    try { return await runLeased(state, () => operation(lease), options.current !== undefined); }
    finally { await revokeLease(state); signal.removeEventListener("abort", abort); lockLeases.delete(lease); }
  });
}

/** WorkerHost calls only after correlating a real reverse effect to its owned
 * endpoint/pending Rust CAS request. This token is local correlation, never
 * evidence that a remote Worker owns a WebLock or that Rust admitted an owner.
 */
export function openAuthRefreshEffectLease(issuer: object, operationId: string, signal: AbortSignal,
  current: () => void): { lease: AuthRefreshEffectLease; close: () => Promise<void> } {
  if (!issuer || typeof issuer !== "object" || typeof operationId !== "string" || operationId.length < 1 || operationId.length > 128)
    throw new Error("invalid_request");
  const state: EffectState = { ...makeState(signal, current), issuer, operationId };
  const lease = opaqueLease() as AuthRefreshEffectLease;
  effectLeases.set(lease, state);
  const abort = () => state.controller.abort();
  signal.addEventListener("abort", abort, { once: true });
  let closing: Promise<void> | null = null;
  return { lease, close: () => {
    if (!closing) closing = revokeLease(state).finally(() => {
      signal.removeEventListener("abort", abort); effectLeases.delete(lease);
    });
    return closing;
  } };
}
export function assertAuthRefreshEffectLease(lease: AuthRefreshEffectLease, issuer: object, operationId: string): void {
  const state = effectLeases.get(lease);
  if (!state || state.issuer !== issuer || state.operationId !== operationId) throw new Error("invalidated_snapshot");
  checkLease(state);
}
/** The callback must await the real IO terminal event, including abort. */
export function withAuthRefreshEffectLease<T>(lease: AuthRefreshEffectLease, issuer: object, operationId: string,
  operation: (signal: AbortSignal) => Promise<T>): Promise<T> {
  assertAuthRefreshEffectLease(lease, issuer, operationId);
  return runLeased(effectLeases.get(lease)!, operation);
}

/** Request success is NOT durability; resolve only on the owned transaction's completion. */
export function committedRequest<T>(transaction: IDBTransaction, request: IDBRequest<T>, signal: AbortSignal): Promise<T> {
  return new Promise((resolve, reject) => {
    let result: T;
    let succeeded = false;
    const cleanup = () => signal.removeEventListener("abort", abort);
    const abort = () => { try { transaction.abort(); } catch { /* Already settled. */ } };
    transaction.oncomplete = () => {
      cleanup();
      if (succeeded && !signal.aborted) resolve(result);
      else reject(new Error(signal.aborted ? "cancelled" : "storage_failed"));
    };
    transaction.onabort = () => { cleanup(); reject(new Error(signal.aborted ? "cancelled" : "storage_failed")); };
    transaction.onerror = () => { /* The abort event owns failure settlement. */ };
    request.onsuccess = () => { result = request.result; succeeded = true; };
    request.onerror = () => { /* Never resolve before transaction completion. */ };
    signal.addEventListener("abort", abort, { once: true });
    if (signal.aborted) abort();
  });
}

/** No schema changes: legacy master_key remains the CryptoKey itself, not JSON. */
export function masterKeyRequest(db: IDBDatabase, mode: "read" | "write" | "delete", key: CryptoKey | null, signal: AbortSignal): Promise<unknown> {
  if (mode === "write" && key === null) return Promise.reject(new Error("invalid_request"));
  const transaction = db.transaction("keys", mode === "read" ? "readonly" : "readwrite");
  const store = transaction.objectStore("keys");
  const request = mode === "read" ? store.get("master_key")
    : mode === "delete" ? store.delete("master_key") : store.put(key, "master_key");
  return committedRequest(transaction, request, signal);
}

/** Thin existing-IDB IO router. The guard is captured from the ORIGINAL actual
 * profile/key/request/lifecycle, never reconstructed from Rust plan owner labels.
 * No key export, enrollment, schema migration, merge policy or automatic writer.
 */
import {executeBrowserMetadataCachePlan} from './browserMetadataCacheIO';
import {executeBrowserMessageCachePlan} from './browserMessageCacheIO';
import type {BrowserCacheEffectHandler} from './browserCacheProtocol';
export function createBrowserCacheEffectHandler(factory:IDBFactory,guard:()=>void):BrowserCacheEffectHandler {
 const lifetime=new AbortController(),active=new Set<Promise<unknown>>();let closed=false;
 return {
  current:guard,
  execute(encoded,signal){
   if(closed||signal.aborted)return Promise.reject(Error('cancelled'));
   const controller=new AbortController();const abort=()=>controller.abort();
   signal.addEventListener('abort',abort,{once:true});lifetime.signal.addEventListener('abort',abort,{once:true});
   if(signal.aborted||lifetime.signal.aborted)abort();
   let terminal:Promise<string>;
   terminal=Promise.resolve().then(async()=>{
    if(closed||controller.signal.aborted)throw Error('cancelled');guard();
    // Exact plan framing/store policy is checked by the existing IO executors.
    const plan:unknown=JSON.parse(encoded);
    const messages=!!plan&&typeof plan==='object'&&Object.hasOwn(plan,'stores');
    const result=await (messages?executeBrowserMessageCachePlan:executeBrowserMetadataCachePlan)(factory,encoded,controller.signal,guard);
    if(controller.signal.aborted)throw Error('cancelled');guard();return result;
   }).finally(()=>{active.delete(terminal);signal.removeEventListener('abort',abort);lifetime.signal.removeEventListener('abort',abort);});
   active.add(terminal);return terminal;
  },
  async close(){closed=true;lifetime.abort();await Promise.allSettled([...active]);}
 };
}

/** Inactive closed transport shapes; Rust owns all restore/merge/key policy. */
import {boundedJson,validReadMessageId,validSavedReadData} from './savedReadProtocol';
import type {SavedReadData} from './savedReadProtocol';
export interface BrowserRetainedRead extends SavedReadData {
 source:'browser_retained_message_cache';readOnly:true;cached:true;fresh:false;historyComplete:false;
