    if(typeof event.data==="object"&&event.data!==null&&"hostEffect" in event.data){void this.effect(event.data);return;}
    if(typeof event.data==='object'&&event.data!==null&&'cacheEffect' in event.data){this.cacheEffect(event.data);return;}
    if (!validResponse(event.data)) { this.close("unavailable"); return; }
