    } else if (event.data.ok && pending.expectedSend) {
      const expected = pending.expectedSend, reply = event.data.send;
      if (!reply || reply.kind !== expected.kind || expected.operationId && reply.operationId !== expected.operationId
        || expected.kind === "started" && (!event.data.status || event.data.status.handle !== expected.handle || event.data.status.generation !== expected.generation || this.sends.has(reply.operationId))
        || reply.kind === "event" && reply.event !== null && !validSendEvent(reply.event, expected.chatId)) { this.close("unavailable"); return; }
      if (reply.kind === "started") this.sends.set(reply.operationId, { handle: expected.handle, generation: expected.generation, chatId: expected.chatId });
      if (reply.kind === "closed" || reply.kind === "event" && (reply.event === null || reply.event.type !== "update")) this.sends.delete(reply.operationId);
    } else {
    const resultId = event.data.ok && (pending.expectedChat?.kind === "savedRead" ? event.data.savedRead?.chat.id : event.data.chat?.id);
    if (event.data.ok && (pending.expectedChat ? !(resultId && event.data.status
      && resultId === pending.expectedChat.chatId && event.data.status.handle === pending.expectedChat.handle
      && event.data.status.generation === pending.expectedChat.generation) : "chat" in event.data || "savedRead" in event.data || "send" in event.data || "snapshot" in event.data)) {
      this.close("unavailable"); return;
    }
    }
    clearTimeout(pending.timer);
    pending.dispose();
    this.pending.delete(event.data.id);
    pending.resolve(event.data);
  };
}

/** Explicit opt-in only; no import-time activation or dependency on existing stores. */
export function bindPageLifecycle(host: BrowserCoreWorkerHost, page: Window, channel: BroadcastChannel): () => void {
  const close = () => host.close();
  const invalidate = (event: MessageEvent<unknown>) => {
    const data = event.data;
    if (typeof data === "object" && data !== null && Object.keys(data).length === 2
      && "version" in data && data.version === 1 && "type" in data && data.type === "invalidate") close();
  };
  page.addEventListener("pagehide", close);
  channel.addEventListener("message", invalidate);
  return () => {
    page.removeEventListener("pagehide", close);
    channel.removeEventListener("message", invalidate);
    host.close();
    channel.close();
  };
}

import {advanceBrowserCachePlan,browserCachePlansComplete,validBrowserCacheReply,validBrowserCachedMetadataRead,validBrowserRetainedRead} from './browserCacheProtocol';
import type {BrowserCacheEffect,BrowserCachePlanState} from './browserCacheProtocol';
import { advanceLocalReadPlan, parseBrowserLocalReadPlan, validLocalCursorReply } from "./protocol";
import type { LocalCursorEffect, LocalReadPlanState } from "./protocol";
import {validCredentialEffectReply,validCredentialEffectMessage,validCredentialCasValidation} from "./credentialCasProtocol";
import type {CredentialEffectMessage} from "./credentialCasProtocol";
import { validBrowserSealedCredentials } from "./browserCredentialStorage";
import { OwnedSendOperation } from "./sendOperation";
import type { SendClient } from "./sendOperation";
import { validSavedRead, validLocalRead, validCheckpointPresentation } from "./savedReadProtocol";
import { clearPasswordRequest, clearExistingKeyRequest, validChat, validRequest } from "./protocol";
import type { CoreResponse, SessionStatus } from "./protocol";
import { consumeWorkerMasterKey } from "./workerCredentials";
