      // callback and carries no admission/publication authority into the new one.
      if(validLocalCursorReply(input)&&input.id<=lastLocalReadId&&(!localRead||input.id<localRead.id))return;
      const pending = localRead?.reply;
      if(!validLocalCursorReply(input)||!localRead?.live||!pending||input.id!==localRead.id||input.effectId!==pending.effectId
        ||input.localReadReply.operationId!==pending.operationId){dispose();return;}
      localRead.reply=null;
      if(input.localReadReply.ok){
        if(new TextEncoder().encode(input.localReadReply.packet).byteLength>pending.maxBytes){pending.reject("unavailable");dispose();return;}
        pending.resolve(input.localReadReply.packet);
      }else pending.reject(input.localReadReply.error);
