    }
    if(typeof input==='object'&&input!==null&&'hostReply' in input){
      if(!validCredentialEffectReply(input)||!casReply||input.id!==casReply.id||input.effectId!==casReply.effectId
        ||input.hostReply.ok&&input.hostReply.result.operationId!==casReply.operationId){dispose();return;}
      const owned=casReply;casReply=null;
      if(input.hostReply.ok)owned.resolve(JSON.stringify(input.hostReply.result));else owned.reject(input.hostReply.error);
      return;
    }
    if (!validRequest(input)) { clearPasswordRequest(input);clearExistingKeyRequest(input); dispose(); return; }
    const { id } = input;
    const fail = (error: "unavailable" | "reauthentication_required" | "session_expired" | "chat_unavailable" | "credential_conflict" | "authentication_failed" | "two_factor_required") => {
      if (!disposed) endpoint.postMessage({ version: 1, id, ok: false, error });
    };
    if (input.operation === "invalidate" || input.operation === "cancel") { dispose(); return; }
