          const event = await active.next(input.handle, input.generation, input.operationId);
          if (disposed) return;
          if (event === null || event.type !== "update") {
            if (sending === active) sending = null;
            if (event?.type === "error" && active.owns(client)) clearClient();
          }
          endpoint.postMessage({ version: 1, id, ok: true, status: null,
            send: { operationId: active.operationId, kind: "event", event } });
