          const status=project(client.admitted_status());
          if (status.persistence!=="memory_only") throw Error("unavailable");
          endpoint.postMessage({version:1,id,ok:true,status});
        } finally { clearPasswordRequest(input);if(passwordAdmission===input)passwordAdmission=null; }
      } else if(input.operation==="restore_existing") {
        const prepare=binding.PreparedBrowserProfile.from_existing_key;
        if(configuration.admission!=="existing_key"||typeof prepare!=="function"
          ||typeof configuration.expectedPrincipal!=="string"
          ||!/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(configuration.expectedPrincipal)
          ||input.profile.principal!==configuration.expectedPrincipal){
