        try {
          const admitted = await withAuthRefreshLock(locks, lifetime.signal, async () => {
            consumed = true; // wasm-bindgen consumes this one-use profile, even on failure.
            return binding.BrowserCoreClient.restore(configuration.apiUrl, configuration.appOrigin, configuration.sessionId, prepared);
          });
          if (disposed) { admitted.invalidate(); admitted.free(); return; }
          client = admitted;
        } finally { if (!consumed) prepared.free(); }
        endpoint.postMessage({ version: 1, id, ok: true, status: project(client.admitted_status()) });
      } else if (input.operation === "start_send") {
        if (!client) { fail("session_expired"); return; }
        const owned = client;
        const authority = project(owned.status(input.handle, input.generation));
        reading = owned;
        try {
          let started: OwnedSendOperation | null = null;
          started = new OwnedSendOperation(owned, authority, input.chatId, input.text,
            operation => withAuthRefreshLock(locks, lifetime.signal, operation), () => {
              if (reading === owned) reading = null;
              if (sending === started && started?.failed) {
                sending = null;
                if (client === owned) client = null;
              }
              if (client !== owned) { owned.invalidate(); owned.free(); }
            });
          sending = started;
        } catch (error) { reading = null; throw error; }
        endpoint.postMessage({ version: 1, id, ok: true, status: authority,
          send: { operationId: sending.operationId, kind: "started" } });
      } else if(input.operation==="rotate_credentials"){
        if(!client){fail("session_expired");return;}
