        let count=0,operationId:string|null=null;
        const current=()=>{if(disposed||client!==owned||lifetime.signal.aborted)throw Error("session_expired");};
        try{
          const encoded=await withAuthRefreshLock(locks,lifetime.signal,async()=>{
            current();
