        }finally{reading=null;if(client!==owned){owned.invalidate();owned.free();}}
      } else if (input.operation === "prepare_credentials" || input.operation === "validate_credentials") {
        if(!client){fail("session_expired");return;}
        const owned=client;project(owned.status(input.handle,input.generation));reading=owned;
        let encoded:string;
        try{encoded=await withAuthRefreshLock(locks,lifetime.signal,async()=> input.operation==="prepare_credentials"
          ?await owned.prepare_credentials(input.handle,input.generation)
          :await owned.validate_credentials(input.handle,input.generation,JSON.stringify(input.snapshot)));}
