    for message in chat.messages {
        let row = js_sys::Object::new();
        set(&row, "id", &JsValue::from_str(&message.id))?;
        set(&row, "role", &JsValue::from_str(&message.role))?;
        set(&row, "content", &JsValue::from_str(&message.content))?;
