#[test]
fn js_pii_numbers_and_decoded_duplicate_keys_have_two_faithful_output_boundaries() {
    let source = r#"[9007199254740993,1e400,-0,{"k":"discarded","k":"kept"}]"#;
    let value = ChatDetailsJson::from_text(source.into()).unwrap();
    let ChatDetailsJsonValue::Array(values) = value.value() else {
        panic!("array")
    };
    assert!(matches!(values[0],ChatDetailsJsonValue::Number(n) if n==9007199254740992.0));
    assert!(matches!(values[1],ChatDetailsJsonValue::Number(n) if n==f64::INFINITY));
    assert!(matches!(values[2],ChatDetailsJsonValue::Number(n) if n==0.0&&n.is_sign_negative()));
    let cli: Value = serde_json::from_str(&value.encoded_json().unwrap()).unwrap();
    assert_eq!(cli, json!([9007199254740992u64,null,0,{"k":"kept"}]));
    let sdk = ChatDetailsJson::from_text(value.sdk_encoded_json().unwrap()).unwrap();
    assert!(sdk.value() == value.value());
    assert!(value.sdk_encoded_json().unwrap().contains("1e400,-0.0"));
    // Source semantics, not original token preservation. Last duplicate wins.
    let ChatDetailsJsonValue::Object(keys) = &values[3] else {
        panic!("object")
    };
    assert_eq!(keys.len(), 1);
    assert_eq!(keys[0].0.utf16_units(), &[107]);
}
#[test]
fn js_pii_decoded_utf16_keys_last_win_and_index_keys_enumerate_first() {
    let value = ChatDetailsJson::from_text(
        r#"{"a":1,"\u0061":2,"2":3,"1":4,"4294967295":5,"01":6}"#.into(),
    )
    .unwrap();
    let ChatDetailsJsonValue::Object(keys) = value.value() else {
        panic!("object")
    };
    let decoded = keys
        .iter()
        .map(|(k, _)| String::from_utf16(k.utf16_units()).unwrap())
        .collect::<Vec<_>>();
    assert_eq!(decoded, vec!["1", "2", "a", "4294967295", "01"]);
    assert!(matches!(keys[2].1,ChatDetailsJsonValue::Number(n) if n==2.0));
    let value=ChatDetailsJson::from_text(r#"{"\ud83d":"discarded","\uD83D":"\udc00","😀":"first","\ud83d\ude00":"kept","literal":"\ud83d"}"#.into()).unwrap();
    let ChatDetailsJsonValue::Object(keys) = value.value() else {
        panic!("object")
    };
    assert_eq!(keys.len(), 3);
    assert_eq!(keys[0].0.utf16_units(), &[0xd83d]);
    let ChatDetailsJsonValue::String(v) = &keys[0].1 else {
        panic!("string")
    };
    assert_eq!(v.utf16_units(), &[0xdc00]);
    assert_eq!(keys[1].0.utf16_units(), &[0xd83d, 0xde00]);
    let encoded = value.encoded_json().unwrap();
    let parsed = ChatDetailsJson::from_text(encoded).unwrap();
    assert!(parsed.value() == value.value());
}
#[test]
fn js_number_layout_keeps_observable_integer_values_and_sdk_underflow_sign() {
    let input = r#"[1e20,1e21,1e-6,1e-7,1000000000000000100,0.1,5e-324,-1e400,-1e-400]"#;
    let expected =
        r#"[100000000000000000000,1e+21,0.000001,1e-7,1000000000000000100,0.1,5e-324,null,0]"#;
    let value = ChatDetailsJson::from_text(input.into()).unwrap();
    let actual: Value = serde_json::from_str(&value.encoded_json().unwrap()).unwrap();
    let expected: Value = serde_json::from_str(expected).unwrap();
    assert_eq!(actual, expected);
    let sdk = ChatDetailsJson::from_text(value.sdk_encoded_json().unwrap()).unwrap();
    assert!(sdk.value() == value.value());
    let ChatDetailsJsonValue::Array(values) = sdk.value() else {
        panic!("array")
    };
    assert!(matches!(values[7],ChatDetailsJsonValue::Number(n) if n==f64::NEG_INFINITY));
    assert!(matches!(values[8],ChatDetailsJsonValue::Number(n) if n==0.0&&n.is_sign_negative()));
}
#[test]
fn normalized_pii_never_changes_absence_null_or_original_admission_and_wipes() {
    let mut read = ChatDetailsRead::default();
    read.messages.push(ChatDetailsMessage {
        pii_mappings: Some(ChatDetailsJson::from_text("[1e400,-0]".into()).unwrap()),
        ..Default::default()
    });
    let cli: Value = serde_json::from_str(&serde_json::to_string(&read).unwrap()).unwrap();
    assert_eq!(cli["messages"][0]["piiMappings"], json!([null, 0]));
    let sdk = read.sdk_json().unwrap();
    let parsed: ChatDetailsRead = serde_json::from_str(&sdk).unwrap();
    let ChatDetailsJsonValue::Array(values) =
        parsed.messages[0].pii_mappings.as_ref().unwrap().value()
    else {
        panic!("array")
    };
    assert!(matches!(values[0],ChatDetailsJsonValue::Number(n) if n==f64::INFINITY));
    let client = Client::new("http://127.0.0.1:9", None).unwrap();
    assert!(matches!(parsed.check(&client), Err(Error::Forbidden)));
    read.wipe();
    assert!(read.messages[0].pii_mappings.is_none());
    assert!(
        ChatDetailsJson::from_text(format!("[{}0{}]", "[".repeat(128), "]".repeat(128))).is_err()
    );
    assert!(ChatDetailsJson::from_text(format!("\"{}\"", "a".repeat(256 * 1024))).is_err());
    for invalid in [
        "01",
        "NaN",
        "Infinity",
        r#"{"x":1} trailing"#,
        r#""\uXX00""#,
    ] {
        assert!(ChatDetailsJson::from_text(invalid.into()).is_err());
    }
}

#[test]
fn sdk_finite_number_wire_preserves_binary64_for_python_integer_boundaries() {
    let value =
        ChatDetailsJson::from_text("[1000000000000000100,9007199254740993,3]".into()).unwrap();
    let sdk = value.sdk_encoded_json().unwrap();
    let raw: Vec<&serde_json::value::RawValue> = serde_json::from_str(&sdk).unwrap();
    assert!(raw[0].get().contains('.') || raw[0].get().contains('e'));
    assert!(raw[1].get().contains('.') || raw[1].get().contains('e'));
    assert_eq!(raw[2].get(), "3");
    let actual: Vec<f64> = serde_json::from_str(&sdk).unwrap();
    assert_eq!(actual[0] as i128, 1000000000000000128);
    assert_eq!(actual[1] as i128, 9007199254740992);
    let cli_text = value.encoded_json().unwrap();
    let cli: Vec<&serde_json::value::RawValue> = serde_json::from_str(&cli_text).unwrap();
    assert_eq!(cli[0].get(), "1000000000000000100");
}

//! Idle account and Team revocation monitoring. Spawned tasks own a socket and
//! public context hash, never account Sessions, master keys, or wrapping keys.
use super::transport::{self, Socket};
use super::plaintext::Plain;
use super::sync_capability::AsyncCryptoScope;
use super::*;
use std::collections::{BTreeMap, BTreeSet};
use std::sync::{
    Arc, Mutex,
    atomic::{AtomicBool, Ordering},
};
use tokio::sync::Notify;
#[path = "cached_view.rs"]
pub mod cached_view;
const MAX_HINTS: usize = 100;

// No payload, credentials, keys, ciphertext, or plaintext enter this mailbox.
#[derive(Default)]
struct Pending {
    refresh: bool,
    chats: BTreeSet<String>,
    recovery: BTreeSet<String>,
    versions: BTreeMap<String, VersionFloor>,
}
#[derive(Default, Clone, Copy)]
struct VersionFloor {
    messages_v: u64,
    metadata_v: u64,
    draft_v: u64,
}
fn version(value: &Value, field: &str) -> Result<u64> {
    match value.get(field) {
        None | Some(Value::Null) => Ok(0),
        Some(value) => value.as_u64().ok_or(Error::Protocol),
    }
}
fn data_version(row: &Value, field: &str) -> Result<u64> {
    Ok(version(row, field)?.max(version(&row["versions"], field)?))
}
fn metadata_version(row: &Value) -> Result<u64> {
    let metadata = data_version(row, "metadata_v")?;
    Ok(if metadata > 0 {
        metadata
    } else {
        data_version(row, "title_v")?
    })
}
fn active_draft(row: &Value) -> Result<bool> {
    let mut active = false;
    for field in ["encrypted_draft_md", "encrypted_draft_preview"] {
        match row.get(field) {
            None | Some(Value::Null) => {}
            Some(Value::String(value)) => active |= !value.is_empty(),
            Some(_) => return Err(Error::Protocol),
        }
    }
    Ok(active)
}
fn matches_revision_floor(row: &Value, floor: &VersionFloor) -> Result<bool> {
    // Canonical metadata omits a tombstone counter for authoritative no-draft.
    let draft_ok = !active_draft(row)? || data_version(row, "draft_v")? >= floor.draft_v;
    Ok(metadata_version(row)? >= floor.metadata_v && draft_ok)
}
fn matches_floor(row: &Value, floor: &VersionFloor) -> Result<bool> {
    Ok(data_version(row, "messages_v")? >= floor.messages_v && matches_revision_floor(row, floor)?)
}
#[derive(Default)]
struct Changes {
    pending: Mutex<Pending>,
    wake: Notify,
}
struct MonitorFence {
    owner: Arc<super::project_task_watch::WatchAuthority>,
    generation: u64,
    team: Option<String>,
    expires_at: Option<u64>,
    cancel: CancellationToken,
    alive: AtomicBool,
    denial: Mutex<Option<ChatMonitorAccessDenial>>,
}
/// Negative observation from an exact authenticated read, never access authority.
#[derive(Clone)]
pub enum ChatMonitorAccessDenial {
    Expired,
    ScopeRevoked,
    ChatUnavailable { chat_id: String },
}
impl MonitorFence {
    fn valid(&self) -> bool {
        self.alive.load(Ordering::Acquire)
            && !self.cancel.is_cancelled()
            && !self.owner.cancel.is_cancelled()
            && self.expires_at.is_none_or(|at| at > now_ms())
    }
}
// Only an exclusive live read installs this audit. It records fixed route
// categories/status, never URLs, response bodies, cookies or arbitrary errors.
#[derive(Clone)]
pub(super) enum MonitorReadOrigin {
    Session,
    Team,
    Chat(String),
}
pub(super) struct MonitorReadAudit {
    fence: Arc<MonitorFence>,
    denial: Option<ChatMonitorAccessDenial>,
}
/// DATA only. No Session, credential revision/ACK, cookies, owner identity,
/// access-denial evidence, operation/lifetime tokens or native journal state.
struct LiveDataBackup {
    chats: BTreeMap<String, Value>,
    chat_arrival_order: Option<Vec<String>>,
    wrappers: Vec<Value>,
    history: BTreeMap<String, Vec<Value>>,
    sync_message_windows: BTreeMap<String, super::sync_windows::CiphertextMessageWindow>,
    selected_first_pages: BTreeMap<String, super::selected_first_page::SelectedFirstPage>,
    embeds: BTreeMap<String, Value>,
    embed_keys: Vec<Value>,
    team_wrapped_key: Option<(String, String)>,
    active_chat: Option<String>,
}
struct LiveReadTransaction<'a> {
    client: &'a mut Client,
    fence: Arc<MonitorFence>,
    backup: Option<LiveDataBackup>,
}
impl<'a> LiveReadTransaction<'a> {
    fn new(client: &'a mut Client, fence: Arc<MonitorFence>) -> Result<Self> {
        client.check_chat_monitor_fence(&fence)?;
        if client.monitor_read_audit.is_some() {
            return Err(Error::Conflict);
        }
        let backup = LiveDataBackup {
            chats: client.chats.clone(),
            chat_arrival_order: client.chat_arrival_order.clone(),
            wrappers: client.wrappers.clone(),
            history: client.history.clone(),
            sync_message_windows: client.sync_message_windows.clone(),
            selected_first_pages: client.selected_first_pages.clone(),
            embeds: client.embeds.clone(),
            embed_keys: client.embed_keys.clone(),
            team_wrapped_key: client.team_wrapped_key.clone(),
            active_chat: client.active_chat.clone(),
        };
        client.monitor_read_audit = Some(MonitorReadAudit {
            fence: fence.clone(),
            denial: None,
        });
        Ok(Self {
            client,
            fence,
            backup: Some(backup),
        })
    }
    fn denied(&self) -> Option<ChatMonitorAccessDenial> {
        self.client
            .monitor_read_audit
            .as_ref()
            .and_then(|audit| audit.denial.clone())
    }
    fn validate_candidate_versions(&self, confirmed_rewinds: &BTreeSet<String>) -> Result<()> {
        if let Some(backup) = &self.backup {
            for (id, prior) in &backup.chats {
                // Missing recent metadata is not a tombstone. Compare actual
                // returned rows only; strict selected absence is handled below.
                if let Some(candidate) = self.client.chats.get(id) {
                    let floor = VersionFloor {
                        messages_v: 0,
                        metadata_v: metadata_version(prior)?,
                        draft_v: data_version(prior, "draft_v")?,
                    };
                    if !matches_revision_floor(candidate, &floor)? {
                        return Err(Error::Offline);
                    }
                    // messages_v is a count: rewind intentionally reduces it.
                    // A lower count needs an exact fresh history replacement,
                    // not an unconditional cache-derived monotonic floor.
                    if data_version(candidate, "messages_v")? < data_version(prior, "messages_v")?
                        && !confirmed_rewinds.contains(id)
                    {
                        return Err(Error::Offline);
                    }
                }
            }
        }
        Ok(())
    }
    fn accept(&mut self) {
        self.backup.take();
    }
    fn same_authorized_owner(&self) -> bool {
        !self.fence.owner.cancel.is_cancelled()
            && Arc::ptr_eq(&self.client.task_watch_authority, &self.fence.owner)
            && self.client.generation == self.fence.generation
            && self.client.require_credentials().is_ok_and(|s| {
                s.active_team_id.as_ref() == self.fence.team.as_ref()
                    && s.paired_session_expires_at.is_none_or(|at| at > now_ms())
            })
            && self.fence.expires_at.is_none_or(|at| at > now_ms())
    }
}
impl std::ops::Deref for LiveReadTransaction<'_> {
    type Target = Client;
    fn deref(&self) -> &Client {
        self.client
    }
}
impl std::ops::DerefMut for LiveReadTransaction<'_> {
    fn deref_mut(&mut self) -> &mut Client {
        self.client
    }
}
impl Drop for LiveReadTransaction<'_> {
    fn drop(&mut self) {
        let fence = self.fence.clone();
        let denial = fence.denial.lock();
        let mut discarded = None;
        if denial.as_ref().is_ok_and(|value| value.is_none())
            && self.same_authorized_owner()
            && let Some(backup) = self.backup.take()
        {
            // Linearize against concurrent keyless security observations. Only
            // pointer/field moves happen under this short lock, never IO or
            // destruction of a potentially large rejected candidate cache.
            discarded = Some(LiveDataBackup {
