        if !self.is_valid() || !Arc::ptr_eq(&self.fence, &hint.fence) {
            return Err(Error::Cancelled);
        }
        let mut pending = self.changes.pending.lock().map_err(|_| Error::Protocol)?;
        merge_pending(&mut pending, hint.pending);
